window.REVISION_SUBJECTS.push({"config":{"examBoard":"AQA GCSE","subjectArea":"Languages","subjectName":"French","brandIcon":"🇫🇷","pageTitle":"French GCSE Revision","brandTitle":"French Revision","brandSubtitle":"AQA GCSE","breadcrumb":"Languages / French","heroEyebrow":"Listening · Speaking · Reading · Writing","papers":[{"id":"Paper 1","label":"Paper 1","title":"Listening","subtitle":"comprehension (text-based practice)"},{"id":"Paper 2","label":"Paper 2","title":"Speaking","subtitle":"role-play & photo card"},{"id":"Paper 3","label":"Paper 3","title":"Reading","subtitle":"comprehension & translation"},{"id":"Paper 4","label":"Paper 4","title":"Writing","subtitle":"production & translation"}],"footerNote":"Questions are original practice items written to match the official AQA GCSE French (8652) specification themes and paper structure. This app has no audio, so Listening items are presented as written transcripts for reading practice, not exam-realistic listening simulation. Model answers are indicative exemplars only, not official AQA mark schemes.","storageId":"aqa_french"},"questions":{"paper1":[{"id":"fr-p1-1-1-0","paper":"Paper 1","module":"1.1","moduleTitle":"Identity and relationships with others","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"Je m'appelle Camille et j'ai seize ans. Dans ma famille, il y a quatre personnes : mon père, ma mère, mon frère et moi. Je m'entends très bien avec ma mère parce qu'elle m'écoute toujours et elle ne me juge jamais. En revanche, je me dispute assez souvent avec mon frère parce qu'il est agaçant et il emprunte mes affaires sans demander. L'année dernière, mes parents ont divorcé, donc je vis maintenant avec ma mère et mon beau-père. Au début, c'était difficile, mais maintenant tout va bien parce que mon beau-père est patient et gentil avec moi.\"\n\nAnswer in English:\n1. How many people are there in Camille's family?\n2. Why does she get on well with her mother? Give one reason.\n3. Why does she argue with her brother?\n4. What happened to her parents last year?\n5. How does she feel about her stepfather now, and why?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. Four people (\"il y a quatre personnes\").\n2. Her mother always listens to her and never judges her (\"elle m'écoute toujours et elle ne me juge jamais\").\n3. Because he is annoying and borrows her things without asking (\"il est agaçant et il emprunte mes affaires sans demander\").\n4. Her parents got divorced (\"mes parents ont divorcé\").\n5. She feels fine now because he is patient and kind to her (\"mon beau-père est patient et gentil avec moi\").","evidence":["s'entendre bien avec","se disputer","ont divorcé","le beau-père","patient(e)"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"1.1-listening-0"},{"id":"fr-p1-1-1-1","paper":"Paper 1","module":"1.1","moduleTitle":"Identity and relationships with others","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"Mon meilleur ami s'appelle Hugo. Il est grand et sportif, et il a les cheveux bruns et bouclés. À mon avis, la qualité la plus importante chez un ami, c'est la loyauté. Hugo est toujours honnête avec moi et il me soutient quand j'ai des problèmes. On se connaît depuis l'école primaire, donc depuis dix ans. Parfois, on se dispute à cause de petites choses, comme le choix d'un film, mais on se réconcilie rapidement parce que notre amitié compte plus que ces disputes.\"\n\nAnswer in English:\n1. How is Hugo described physically? Give two details.\n2. What quality does the speaker think matters most in a friend?\n3. How long have they known each other?\n4. What do they sometimes argue about?\n5. Why do they make up quickly after an argument?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. Tall and sporty, with curly brown hair (\"grand et sportif\", \"les cheveux bruns et bouclés\").\n2. Loyalty (\"la loyauté\").\n3. Ten years, since primary school (\"depuis l'école primaire, donc depuis dix ans\").\n4. Small things, like choosing a film (\"le choix d'un film\").\n5. Because their friendship matters more than the arguments (\"notre amitié compte plus que ces disputes\").","evidence":["la loyauté","soutenir","se réconcilier","on se connaît depuis","compter plus que"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"1.1-listening-1"},{"id":"fr-p1-1-2-0","paper":"Paper 1","module":"1.2","moduleTitle":"Healthy living and lifestyle","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"Pour rester en forme, je fais du sport trois fois par semaine : je joue au foot le mardi et je vais à la piscine le samedi. J'essaie de manger équilibré, donc je mange beaucoup de fruits et de légumes, et j'évite les matières grasses et sucrées. Par contre, mon frère ne fait jamais de sport et il mange souvent des frites et des bonbons. Je pense qu'il devrait changer ses habitudes parce que ce n'est pas bon pour sa santé.\"\n\nAnswer in English:\n1. How often does the speaker do sport, and what activities do they mention?\n2. What does the speaker say about their diet?\n3. What does the speaker avoid eating?\n4. What is different about the speaker's brother's lifestyle?\n5. What does the speaker think their brother should do, and why?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. Three times a week: football on Tuesday and swimming on Saturday (\"je fais du sport trois fois par semaine... le foot le mardi... la piscine le samedi\").\n2. They try to eat a balanced diet, with lots of fruit and vegetables (\"j'essaie de manger équilibré... beaucoup de fruits et de légumes\").\n3. Fatty and sugary foods (\"les matières grasses et sucrées\").\n4. He never does sport and often eats chips and sweets (\"il ne fait jamais de sport et il mange souvent des frites et des bonbons\").\n5. He should change his habits because it is not good for his health (\"il devrait changer ses habitudes parce que ce n'est pas bon pour sa santé\").","evidence":["rester en forme","manger équilibré","éviter","les matières grasses/sucrées","il devrait"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"1.2-listening-0"},{"id":"fr-p1-1-2-1","paper":"Paper 1","module":"1.2","moduleTitle":"Healthy living and lifestyle","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"L'année dernière, j'étais souvent stressé à cause des examens et je ne dormais pas assez, parfois seulement cinq heures par nuit. Un jour, j'ai décidé de changer ma routine : maintenant, je me couche plus tôt et je me détends en lisant avant de dormir. De plus, j'ai arrêté de boire des boissons énergisantes. Depuis, je me sens beaucoup mieux et je suis moins fatigué en classe.\"\n\nAnswer in English:\n1. Why was the speaker often stressed last year?\n2. How many hours did they sometimes sleep?\n3. What two changes did they make to their routine?\n4. What did they stop drinking?\n5. How do they feel now?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. Because of exams (\"stressé à cause des examens\").\n2. Sometimes only five hours a night (\"seulement cinq heures par nuit\").\n3. They go to bed earlier and relax by reading before sleeping (\"je me couche plus tôt et je me détends en lisant\").\n4. Energy drinks (\"des boissons énergisantes\").\n5. Much better and less tired in class (\"je me sens beaucoup mieux et je suis moins fatigué\").","evidence":["stressé(e)","se coucher","se détendre","arrêter de + infinitive","fatigué(e)"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"1.2-listening-1"},{"id":"fr-p1-1-3-0","paper":"Paper 1","module":"1.3","moduleTitle":"Education and work","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"Au lycée, j'ai cours du lundi au vendredi, de huit heures à seize heures. Ma matière préférée est l'anglais parce que le professeur est dynamique et les cours sont intéressants. En revanche, je déteste la physique parce que je trouve ça trop difficile et je n'ai jamais de bonnes notes. L'année prochaine, je vais passer mes examens du brevet, donc je dois travailler plus dur. Après le lycée, j'espère faire des études de médecine à l'université.\"\n\nAnswer in English:\n1. What days and hours does the speaker have lessons?\n2. What is their favourite subject, and why?\n3. Which subject do they dislike, and why?\n4. What are they going to do next year?\n5. What do they hope to study after lycée?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. Monday to Friday, 8am to 4pm (\"du lundi au vendredi, de huit heures à seize heures\").\n2. English, because the teacher is dynamic and lessons are interesting (\"l'anglais parce que le professeur est dynamique\").\n3. Physics, because they find it too difficult and never get good marks (\"la physique parce que je trouve ça trop difficile\").\n4. They are going to sit their brevet exams (\"je vais passer mes examens du brevet\").\n5. Medicine at university (\"faire des études de médecine à l'université\").","evidence":["ma matière préférée","je déteste","je vais passer mes examens","faire des études de"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"1.3-listening-0"},{"id":"fr-p1-1-3-1","paper":"Paper 1","module":"1.3","moduleTitle":"Education and work","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"L'été dernier, j'ai fait un stage en entreprise dans un hôpital pendant une semaine. J'ai beaucoup appris sur le métier d'infirmier et j'ai aidé le personnel avec des tâches simples. En plus, le week-end, j'ai un petit boulot dans un supermarché pour gagner de l'argent de poche. C'est fatigant, mais ça m'apprend à être responsable. Plus tard, je voudrais travailler dans le domaine médical parce que j'aime aider les autres.\"\n\nAnswer in English:\n1. Where did the speaker do work experience last summer, and for how long?\n2. What did they learn about during the placement?\n3. What part-time job do they have?\n4. Why do they do this job?\n5. What career do they want in the future, and why?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. In a hospital, for one week (\"dans un hôpital pendant une semaine\").\n2. The job of a nurse (\"le métier d'infirmier\").\n3. A job in a supermarket (\"un petit boulot dans un supermarché\").\n4. To earn pocket money (\"pour gagner de l'argent de poche\").\n5. To work in the medical field, because they like helping others (\"travailler dans le domaine médical parce que j'aime aider les autres\").","evidence":["un stage en entreprise","un petit boulot","gagner de l'argent de poche","plus tard, je voudrais"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"1.3-listening-1"},{"id":"fr-p1-2-1-0","paper":"Paper 1","module":"2.1","moduleTitle":"Free-time activities","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"Pendant mon temps libre, je suis passionné de jeux vidéo. Je joue presque tous les jours avec mes amis en ligne. Le week-end dernier, je suis allé au cinéma avec ma sœur pour voir un film d'action. J'aime aussi lire des romans fantastiques, mais je n'ai pas beaucoup de temps pendant la semaine à cause des devoirs. À mon avis, il est important d'avoir des loisirs variés pour se détendre.\"\n\nAnswer in English:\n1. What is the speaker passionate about, and how often do they do it?\n2. What did the speaker do last weekend?\n3. What does the speaker also enjoy, but with a limitation?\n4. Why do they not have much time during the week?\n5. What does the speaker think is important?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. Video games, almost every day with friends online (\"je joue presque tous les jours avec mes amis en ligne\").\n2. Went to the cinema with their sister to see an action film (\"je suis allé au cinéma avec ma sœur\").\n3. Reading fantasy novels, but not much time during the week (\"j'aime aussi lire des romans fantastiques\").\n4. Because of homework (\"à cause des devoirs\").\n5. That it is important to have varied hobbies to relax (\"il est important d'avoir des loisirs variés pour se détendre\").","evidence":["être passionné(e) de","je suis allé(e)","à cause de","se détendre"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"2.1-listening-0"},{"id":"fr-p1-2-1-1","paper":"Paper 1","module":"2.1","moduleTitle":"Free-time activities","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"Chaque samedi, je fais du shopping avec mes copines au centre-ville. On aime essayer des vêtements, mais on n'achète pas toujours quelque chose parce que c'est cher. Après, on va souvent dans un café pour discuter. Une fois par mois, je vais aussi à la patinoire avec mon frère parce que j'adore patiner, même si je tombe parfois !\"\n\nAnswer in English:\n1. What does the speaker do every Saturday, and with whom?\n2. What do they like doing, but don't always do?\n3. Why don't they always buy something?\n4. Where do they often go afterwards?\n5. What does the speaker do once a month, and what do they say about it?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. Goes shopping in the town centre with friends (\"je fais du shopping avec mes copines au centre-ville\").\n2. Trying on clothes, but don't always buy something (\"on aime essayer des vêtements\").\n3. Because it is expensive (\"parce que c'est cher\").\n4. To a café to chat (\"dans un café pour discuter\").\n5. Goes ice-skating with their brother; they love it, even though they sometimes fall (\"j'adore patiner, même si je tombe parfois\").","evidence":["faire du shopping","une fois par mois","la patinoire","même si"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"2.1-listening-1"},{"id":"fr-p1-2-2-0","paper":"Paper 1","module":"2.2","moduleTitle":"Customs, festivals and celebrations","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"Chaque année, le 14 juillet, la France célèbre sa fête nationale. L'année dernière, je suis allé voir le défilé militaire avec ma famille, puis le soir, nous avons regardé les feux d'artifice près de la rivière. C'était magnifique ! Après, nous avons mangé une glace ensemble. Je trouve que cette fête est importante parce qu'elle rassemble les gens et célèbre l'histoire du pays.\"\n\nAnswer in English:\n1. What does France celebrate every year on 14 July?\n2. What did the speaker do last year during the day?\n3. What did they do in the evening?\n4. What did they do after the fireworks?\n5. Why does the speaker think this festival is important?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. Its national day/Bastille Day (\"sa fête nationale\").\n2. Went to see the military parade with their family (\"je suis allé voir le défilé militaire avec ma famille\").\n3. Watched the fireworks near the river (\"nous avons regardé les feux d'artifice près de la rivière\").\n4. Ate an ice cream together (\"nous avons mangé une glace ensemble\").\n5. Because it brings people together and celebrates the country's history (\"elle rassemble les gens et célèbre l'histoire du pays\").","evidence":["la fête nationale","le défilé","les feux d'artifice","rassembler"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"2.2-listening-0"},{"id":"fr-p1-2-2-1","paper":"Paper 1","module":"2.2","moduleTitle":"Customs, festivals and celebrations","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"Dans ma famille, Noël est la fête la plus importante de l'année. On se réunit toujours chez mes grands-parents le 24 décembre pour un grand repas de fête avec de la dinde et des marrons. À minuit, on ouvre les cadeaux ensemble. L'année prochaine, je vais inviter aussi mes cousins d'Espagne parce qu'ils n'ont jamais passé Noël en France.\"\n\nAnswer in English:\n1. Which celebration is the most important in the speaker's family?\n2. Where do they always gather, and when?\n3. What do they eat at the festive meal?\n4. What do they do at midnight?\n5. What is the speaker planning for next year, and why?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. Christmas (\"Noël est la fête la plus importante\").\n2. At their grandparents' house, on 24 December (\"chez mes grands-parents le 24 décembre\").\n3. Turkey and chestnuts (\"de la dinde et des marrons\").\n4. Open the presents together (\"on ouvre les cadeaux ensemble\").\n5. To invite their cousins from Spain, because they have never spent Christmas in France (\"ils n'ont jamais passé Noël en France\").","evidence":["se réunir","un repas de fête","à minuit","je vais inviter"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"2.2-listening-1"},{"id":"fr-p1-2-3-0","paper":"Paper 1","module":"2.3","moduleTitle":"Celebrity culture","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"Ma chanteuse préférée s'appelle Clara Luciani. Je l'admire parce qu'elle a beaucoup de talent et elle écrit ses propres chansons. L'année dernière, je suis allé(e) à son concert avec ma cousine, et c'était une expérience incroyable. Cependant, je pense que la célébrité apporte aussi des inconvénients, comme la perte de la vie privée. Les paparazzis suivent souvent les stars partout, et je trouve ça injuste.\"\n\nAnswer in English:\n1. Who is the speaker's favourite singer?\n2. Why do they admire her?\n3. What did the speaker do last year?\n4. What disadvantage of fame does the speaker mention?\n5. What do they think is unfair?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. Clara Luciani.\n2. Because she has a lot of talent and writes her own songs (\"elle a beaucoup de talent et elle écrit ses propres chansons\").\n3. Went to her concert with their cousin (\"je suis allé(e) à son concert avec ma cousine\").\n4. Loss of privacy (\"la perte de la vie privée\").\n5. That paparazzi often follow stars everywhere (\"les paparazzis suivent souvent les stars partout\").","evidence":["j'admire","la perte de la vie privée","les paparazzis","injuste"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"2.3-listening-0"},{"id":"fr-p1-2-3-1","paper":"Paper 1","module":"2.3","moduleTitle":"Celebrity culture","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"De plus en plus de jeunes rêvent de devenir influenceurs sur les réseaux sociaux. Mon frère suit plusieurs influenceurs qui parlent de jeux vidéo, et il voudrait faire la même chose un jour. À mon avis, c'est un métier intéressant, mais aussi risqué, parce qu'il n'y a pas toujours de sécurité financière. De plus, certains influenceurs subissent une forte pression pour toujours paraître parfaits en ligne.\"\n\nAnswer in English:\n1. What do more and more young people dream of becoming?\n2. What does the speaker's brother follow, and what does he want to do?\n3. What does the speaker think about this career?\n4. What is one risk mentioned?\n5. What pressure do some influencers face?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. Influencers on social media (\"devenir influenceurs sur les réseaux sociaux\").\n2. Follows gaming influencers and wants to do the same one day (\"il voudrait faire la même chose un jour\").\n3. Interesting but risky (\"un métier intéressant, mais aussi risqué\").\n4. No financial security (\"il n'y a pas toujours de sécurité financière\").\n5. Pressure to always appear perfect online (\"une forte pression pour toujours paraître parfaits en ligne\").","evidence":["un(e) influenceur/influenceuse","risqué(e)","la sécurité financière","la pression"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"2.3-listening-1"},{"id":"fr-p1-3-1-0","paper":"Paper 1","module":"3.1","moduleTitle":"Travel and tourism, including places of interest","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"L'été dernier, je suis parti(e) en vacances en Espagne avec ma famille. Nous avons pris l'avion et nous sommes restés une semaine dans un hôtel près de la plage. Il faisait très beau et chaud, donc nous avons passé beaucoup de temps à nager dans la mer. Un jour, nous avons visité un monument historique dans la vieille ville, et j'ai adoré découvrir la culture locale. L'année prochaine, j'aimerais voyager au Portugal.\"\n\nAnswer in English:\n1. Where did the speaker go on holiday last summer, and with whom?\n2. How did they travel, and how long did they stay?\n3. What was the weather like?\n4. What did they visit one day?\n5. Where would the speaker like to travel next year?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. To Spain, with their family (\"en vacances en Espagne avec ma famille\").\n2. By plane, and stayed one week (\"nous avons pris l'avion... une semaine\").\n3. Very nice and hot (\"il faisait très beau et chaud\").\n4. A historic monument in the old town (\"un monument historique dans la vieille ville\").\n5. Portugal (\"j'aimerais voyager au Portugal\").","evidence":["je suis parti(e) en vacances","il faisait beau","un monument historique","j'aimerais voyager"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"3.1-listening-0"},{"id":"fr-p1-3-1-1","paper":"Paper 1","module":"3.1","moduleTitle":"Travel and tourism, including places of interest","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"Pour réserver nos vacances, mes parents utilisent souvent Internet pour comparer les prix des hôtels. Cette année, nous allons faire du camping dans les Alpes parce que ma mère adore la montagne. Avant, nous allons passer à l'office de tourisme pour obtenir une carte de la région et des informations sur les randonnées. Je suis un peu inquiet parce que je n'ai jamais fait de camping, mais je suis aussi curieux de découvrir cette expérience.\"\n\nAnswer in English:\n1. What do the speaker's parents often use to book holidays?\n2. What are they going to do this year, and why?\n3. What are they going to do before, and why?\n4. How does the speaker feel about camping?\n5. Why does the speaker feel curious?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. The internet, to compare hotel prices (\"utilisent souvent Internet pour comparer les prix des hôtels\").\n2. Go camping in the Alps, because the mother loves the mountains (\"ma mère adore la montagne\").\n3. Go to the tourist office to get a map and information on hikes (\"obtenir une carte de la région et des informations sur les randonnées\").\n4. A bit worried, because they have never been camping (\"je n'ai jamais fait de camping\").\n5. Because they want to discover this new experience (\"curieux de découvrir cette expérience\").","evidence":["réserver","l'office de tourisme","une randonnée","inquiet/inquiète","curieux/curieuse"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"3.1-listening-1"},{"id":"fr-p1-3-2-0","paper":"Paper 1","module":"3.2","moduleTitle":"Media and technology","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"Je passe environ trois heures par jour sur mon portable, surtout sur les réseaux sociaux. D'un côté, c'est pratique parce que je peux communiquer facilement avec mes amis. D'un autre côté, je pense que c'est parfois néfaste parce que ça m'empêche de me concentrer sur mes devoirs. Mes parents veulent que je limite mon temps d'écran, surtout le soir avant de dormir.\"\n\nAnswer in English:\n1. How much time does the speaker spend on their phone per day, and on what mainly?\n2. What advantage of phones does the speaker mention?\n3. What disadvantage do they mention?\n4. What do the speaker's parents want them to do?\n5. When especially do the parents want this?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. About three hours a day, mainly on social media (\"environ trois heures par jour sur mon portable, surtout sur les réseaux sociaux\").\n2. They can communicate easily with friends (\"je peux communiquer facilement avec mes amis\").\n3. It stops them concentrating on homework (\"ça m'empêche de me concentrer sur mes devoirs\").\n4. Limit their screen time (\"limiter mon temps d'écran\").\n5. Especially in the evening before sleeping (\"surtout le soir avant de dormir\").","evidence":["le temps d'écran","d'un côté... d'un autre côté","néfaste","limiter"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"3.2-listening-0"},{"id":"fr-p1-3-2-1","paper":"Paper 1","module":"3.2","moduleTitle":"Media and technology","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"L'année dernière, j'ai créé un compte sur un nouveau réseau social, mais j'ai vite compris qu'il fallait faire attention à ma vie privée. Je ne partage jamais mon adresse ou des informations personnelles en ligne. Mes parents m'ont expliqué qu'il y a des gens malhonnêtes sur Internet, donc maintenant je vérifie toujours qui peut voir mes publications.\"\n\nAnswer in English:\n1. What did the speaker do last year?\n2. What did they quickly understand?\n3. What does the speaker never share online?\n4. What did the speaker's parents explain?\n5. What does the speaker now always check?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. Created an account on a new social network (\"j'ai créé un compte sur un nouveau réseau social\").\n2. That they needed to be careful about privacy (\"il fallait faire attention à ma vie privée\").\n3. Their address or personal information (\"mon adresse ou des informations personnelles\").\n4. That there are dishonest people on the internet (\"il y a des gens malhonnêtes sur Internet\").\n5. Who can see their posts (\"qui peut voir mes publications\").","evidence":["la vie privée","partager","malhonnête","vérifier"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"3.2-listening-1"},{"id":"fr-p1-3-3-0","paper":"Paper 1","module":"3.3","moduleTitle":"The environment and where people live","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"J'habite dans une petite ville à la campagne. J'aime vivre ici parce que l'air est plus propre qu'en ville et il y a moins de pollution. Cependant, il n'y a pas beaucoup de transports en commun, donc mes parents doivent souvent me conduire en voiture. Le mois dernier, j'ai participé à un nettoyage de la rivière avec mon école, et j'ai trouvé beaucoup de déchets en plastique. Je pense qu'il faut faire plus d'efforts pour protéger notre environnement local.\"\n\nAnswer in English:\n1. Where does the speaker live?\n2. Why does the speaker like living there?\n3. What problem does the speaker mention about transport?\n4. What did the speaker do last month?\n5. What does the speaker think needs to happen?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. In a small town in the countryside (\"une petite ville à la campagne\").\n2. The air is cleaner and there is less pollution than in the city (\"l'air est plus propre qu'en ville et il y a moins de pollution\").\n3. Not much public transport, so parents often have to drive them (\"il n'y a pas beaucoup de transports en commun\").\n4. Took part in a river clean-up with their school (\"j'ai participé à un nettoyage de la rivière avec mon école\").\n5. That more effort is needed to protect the local environment (\"il faut faire plus d'efforts pour protéger notre environnement local\").","evidence":["plus propre que","les transports en commun","les déchets en plastique","il faut faire plus d'efforts"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"3.3-listening-0"},{"id":"fr-p1-3-3-1","paper":"Paper 1","module":"3.3","moduleTitle":"The environment and where people live","question":"Listening-style written practice (read the transcript — there is no audio in this app):\n\n\"Dans ma famille, nous essayons de protéger la planète au quotidien. Nous recyclons le verre, le papier et le plastique, et nous économisons l'eau en prenant des douches plus courtes. L'année dernière, mes parents ont installé des panneaux solaires sur le toit pour économiser l'énergie. Je pense que chaque petit geste compte pour lutter contre le réchauffement climatique.\"\n\nAnswer in English:\n1. What does the speaker's family try to do daily?\n2. What three things do they recycle?\n3. How do they save water?\n4. What did the speaker's parents install last year, and why?\n5. What does the speaker believe about small actions?","marks":5,"command":"Listen and answer","sourcePage":null,"rubric":"","modelAnswer":"1. Protect the planet (\"protéger la planète au quotidien\").\n2. Glass, paper and plastic (\"le verre, le papier et le plastique\").\n3. By taking shorter showers (\"en prenant des douches plus courtes\").\n4. Solar panels, to save energy (\"des panneaux solaires sur le toit pour économiser l'énergie\").\n5. That every small action counts in fighting climate change (\"chaque petit geste compte pour lutter contre le réchauffement climatique\").","evidence":["recycler","économiser l'eau/l'énergie","des panneaux solaires","le réchauffement climatique"],"examTip":"Underline key nouns, verbs and negatives in the transcript first, then match each English question to the matching French sentence before answering — don't translate word-for-word.","answerTopic":"3.3-listening-1"}],"paper2":[{"id":"fr-p2-1-1-0","paper":"Paper 2","module":"1.1","moduleTitle":"Identity and relationships with others","question":"Describe this photo of a family eating a meal together around a table at home. Say who you think the people are, what they are doing, and give your opinion on family mealtimes.","marks":10,"command":"Describe the photo","sourcePage":null,"rubric":"","modelAnswer":"Sur la photo, je vois une famille qui dîne ensemble dans la cuisine. Il y a une mère, un père et deux enfants, et ils ont l'air heureux et détendus. Ils parlent et ils rient en mangeant. À mon avis, c'est important de manger en famille parce que ça permet de discuter de la journée et de rester proches. Dans ma famille, on mange ensemble presque tous les soirs, et je trouve ça essentiel.\n\n(English translation: In the photo, I can see a family having dinner together in the kitchen. There is a mother, a father and two children, and they look happy and relaxed. They are talking and laughing while they eat. In my opinion, it is important to eat as a family because it allows you to talk about the day and stay close. In my family, we eat together almost every evening, and I think that is essential.)\n\nUseful phrases: sur la photo, je vois...; ils ont l'air + adjective; à mon avis, c'est important de...","evidence":["sur la photo, je vois...","ils ont l'air + adjective","à mon avis, c'est important de..."],"examTip":"Structure your description in three parts: what you see, an opinion, and a personal link — this shows range beyond simple description.","answerTopic":"1.1-speaking-0"},{"id":"fr-p2-1-1-1","paper":"Paper 2","module":"1.1","moduleTitle":"Identity and relationships with others","question":"Role-play: your teacher plays a French friend. You must (1) say who is in your family, (2) describe your relationship with a brother/sister, and (3) answer an unexpected question about a recent disagreement.","marks":10,"command":"Role-play","sourcePage":null,"rubric":"","modelAnswer":"— Dans ma famille, il y a mes parents, ma petite sœur et moi.\n— Je m'entends bien avec ma sœur, mais elle est parfois agaçante parce qu'elle entre dans ma chambre sans frapper.\n— (Question imprévue) La dernière fois qu'on s'est disputés, c'était à cause de la télécommande ! On s'est réconciliés le soir même.\n\n(English translation: — In my family there are my parents, my little sister and me.\n— I get on well with my sister, but she is sometimes annoying because she comes into my room without knocking.\n— (Unexpected question) The last time we argued, it was about the remote control! We made up that same evening.)\n\nUseful phrases: je m'entends bien avec; sans frapper; on s'est réconciliés","evidence":["je m'entends bien avec","sans frapper","on s'est réconciliés"],"examTip":"Prepare flexible phrases for the unexpected question in advance; you cannot predict it exactly, but a stock structure (opinion + reason + example) will fit almost any topic.","answerTopic":"1.1-speaking-1"},{"id":"fr-p2-1-2-0","paper":"Paper 2","module":"1.2","moduleTitle":"Healthy living and lifestyle","question":"Describe this photo of teenagers playing football in a park on a sunny day. Say what they are doing, how they might be feeling, and give your opinion on the importance of sport for young people.","marks":10,"command":"Describe the photo","sourcePage":null,"rubric":"","modelAnswer":"Sur la photo, il y a un groupe d'adolescents qui jouent au foot dans un parc. Ils courent et ils ont l'air en pleine forme et contents. À mon avis, le sport est essentiel pour les jeunes parce qu'il aide à rester en bonne santé et à réduire le stress. Personnellement, je fais du sport deux fois par semaine et je me sens toujours mieux après.\n\n(English translation: In the photo, there is a group of teenagers playing football in a park. They are running and they look very fit and happy. In my opinion, sport is essential for young people because it helps you stay healthy and reduce stress. Personally, I do sport twice a week and I always feel better afterwards.)\n\nUseful phrases: ils ont l'air + adjective; il aide à + infinitive; je me sens mieux","evidence":["ils ont l'air + adjective","il aide à + infinitive","je me sens mieux"],"examTip":"Structure your description in three parts: what you see, an opinion, and a personal link — this shows range beyond simple description.","answerTopic":"1.2-speaking-0"},{"id":"fr-p2-1-2-1","paper":"Paper 2","module":"1.2","moduleTitle":"Healthy living and lifestyle","question":"Role-play: your teacher plays a French doctor/parent. You must (1) say whether you think your lifestyle is healthy, (2) mention one thing you should change, and (3) answer an unexpected question about what you ate yesterday.","marks":10,"command":"Role-play","sourcePage":null,"rubric":"","modelAnswer":"— Je pense que ma vie est assez saine, mais je ne dors pas toujours assez.\n— Je devrais me coucher plus tôt pendant la semaine.\n— (Question imprévue) Hier, j'ai mangé une salade au déjeuner et des pâtes avec des légumes au dîner.\n\n(English translation: — I think my life is fairly healthy, but I don't always sleep enough.\n— I should go to bed earlier during the week.\n— (Unexpected question) Yesterday, I ate a salad for lunch and pasta with vegetables for dinner.)\n\nUseful phrases: assez sain(e); je devrais + infinitive; j'ai mangé/j'ai bu","evidence":["assez sain(e)","je devrais + infinitive","j'ai mangé/j'ai bu"],"examTip":"Prepare flexible phrases for the unexpected question in advance; you cannot predict it exactly, but a stock structure (opinion + reason + example) will fit almost any topic.","answerTopic":"1.2-speaking-1"},{"id":"fr-p2-1-3-0","paper":"Paper 2","module":"1.3","moduleTitle":"Education and work","question":"Describe this photo of students sitting at desks in a classroom, listening to a teacher. Say what is happening, what subject you think it might be, and give your opinion on school life.","marks":10,"command":"Describe the photo","sourcePage":null,"rubric":"","modelAnswer":"Sur la photo, je vois des élèves assis à leur bureau qui écoutent attentivement leur professeur. Je pense que c'est peut-être un cours d'histoire parce qu'il y a une carte au mur. À mon avis, l'école est importante parce qu'elle nous prépare pour notre avenir, même si les journées sont parfois longues et fatigantes.\n\n(English translation: In the photo, I can see students sitting at their desks listening attentively to their teacher. I think it might be a history lesson because there is a map on the wall. In my opinion, school is important because it prepares us for our future, even if the days are sometimes long and tiring.)\n\nUseful phrases: je pense que c'est peut-être...; elle nous prépare pour...; même si","evidence":["je pense que c'est peut-être...","elle nous prépare pour...","même si"],"examTip":"Structure your description in three parts: what you see, an opinion, and a personal link — this shows range beyond simple description.","answerTopic":"1.3-speaking-0"},{"id":"fr-p2-1-3-1","paper":"Paper 2","module":"1.3","moduleTitle":"Education and work","question":"Role-play: your teacher plays a French employer. You must (1) say what work experience you have done, (2) describe one task you did, and (3) answer an unexpected question about why you want the job.","marks":10,"command":"Role-play","sourcePage":null,"rubric":"","modelAnswer":"— J'ai fait un stage dans un magasin pendant une semaine.\n— J'ai aidé les clients et j'ai rangé les rayons.\n— (Question imprévue) Je veux ce poste parce que j'adore travailler avec le public et je suis très organisé(e).\n\n(English translation: — I did a work placement in a shop for a week.\n— I helped customers and tidied the shelves.\n— (Unexpected question) I want this job because I love working with the public and I am very organised.)\n\nUseful phrases: j'ai fait un stage; j'ai aidé/j'ai rangé; je veux ce poste parce que","evidence":["j'ai fait un stage","j'ai aidé/j'ai rangé","je veux ce poste parce que"],"examTip":"Prepare flexible phrases for the unexpected question in advance; you cannot predict it exactly, but a stock structure (opinion + reason + example) will fit almost any topic.","answerTopic":"1.3-speaking-1"},{"id":"fr-p2-2-1-0","paper":"Paper 2","module":"2.1","moduleTitle":"Free-time activities","question":"Describe this photo of friends at the cinema, holding popcorn and smiling. Say what they are doing, how often you go to the cinema, and give your opinion on this leisure activity.","marks":10,"command":"Describe the photo","sourcePage":null,"rubric":"","modelAnswer":"Sur la photo, je vois un groupe d'amis au cinéma qui tiennent du pop-corn et qui sourient. Ils ont l'air de s'amuser beaucoup. Personnellement, je vais au cinéma environ une fois par mois avec mes amis. À mon avis, c'est une activité géniale parce qu'on peut se détendre tout en passant du temps ensemble.\n\n(English translation: In the photo, I can see a group of friends at the cinema holding popcorn and smiling. They look like they are having a lot of fun. Personally, I go to the cinema about once a month with my friends. In my opinion, it's a great activity because you can relax while spending time together.)\n\nUseful phrases: ils ont l'air de + infinitive; environ une fois par mois; tout en + gerund","evidence":["ils ont l'air de + infinitive","environ une fois par mois","tout en + gerund"],"examTip":"Structure your description in three parts: what you see, an opinion, and a personal link — this shows range beyond simple description.","answerTopic":"2.1-speaking-0"},{"id":"fr-p2-2-1-1","paper":"Paper 2","module":"2.1","moduleTitle":"Free-time activities","question":"Role-play: your teacher plays a French friend planning a weekend outing. You must (1) suggest an activity, (2) say why you like that activity, and (3) answer an unexpected question about the cost.","marks":10,"command":"Role-play","sourcePage":null,"rubric":"","modelAnswer":"— On pourrait aller à la patinoire samedi ?\n— J'adore patiner parce que c'est amusant et ça change de la routine.\n— (Question imprévue) Je pense que ça coûte environ dix euros l'entrée.\n\n(English translation: — Could we go ice-skating on Saturday?\n— I love ice-skating because it's fun and it's a change from the routine.\n— (Unexpected question) I think the entrance costs around ten euros.)\n\nUseful phrases: on pourrait + infinitive; ça change de la routine; ça coûte environ...","evidence":["on pourrait + infinitive","ça change de la routine","ça coûte environ..."],"examTip":"Prepare flexible phrases for the unexpected question in advance; you cannot predict it exactly, but a stock structure (opinion + reason + example) will fit almost any topic.","answerTopic":"2.1-speaking-1"},{"id":"fr-p2-2-2-0","paper":"Paper 2","module":"2.2","moduleTitle":"Customs, festivals and celebrations","question":"Describe this photo of a crowd watching fireworks at night near a river. Say what is happening, how people might feel, and give your opinion on festival celebrations.","marks":10,"command":"Describe the photo","sourcePage":null,"rubric":"","modelAnswer":"Sur la photo, il y a une foule de gens qui regardent des feux d'artifice au-dessus d'une rivière la nuit. Les gens ont l'air émerveillés et joyeux. À mon avis, les fêtes comme celle-ci sont importantes parce qu'elles créent un sentiment de communauté et de fierté nationale.\n\n(English translation: In the photo, there is a crowd of people watching fireworks above a river at night. The people look amazed and joyful. In my opinion, festivals like this one are important because they create a sense of community and national pride.)\n\nUseful phrases: une foule de gens; ils ont l'air + adjective; un sentiment de...","evidence":["une foule de gens","ils ont l'air + adjective","un sentiment de..."],"examTip":"Structure your description in three parts: what you see, an opinion, and a personal link — this shows range beyond simple description.","answerTopic":"2.2-speaking-0"},{"id":"fr-p2-2-2-1","paper":"Paper 2","module":"2.2","moduleTitle":"Customs, festivals and celebrations","question":"Role-play: your teacher plays a French friend discussing a celebration. You must (1) say which festival you prefer, (2) explain why, and (3) answer an unexpected question about what you did last year for that festival.","marks":10,"command":"Role-play","sourcePage":null,"rubric":"","modelAnswer":"— Je préfère Noël parce que j'adore passer du temps en famille.\n— C'est une fête chaleureuse avec beaucoup de traditions.\n— (Question imprévue) L'année dernière, nous avons décoré le sapin ensemble et j'ai reçu un vélo.\n\n\n(English translation: — I prefer Christmas because I love spending time with my family.\n— It's a warm celebration with lots of traditions.\n— (Unexpected question) Last year, we decorated the Christmas tree together and I received a bike.)\n\nUseful phrases: je préfère... parce que; chaleureux/chaleureuse; j'ai reçu","evidence":["je préfère... parce que","chaleureux/chaleureuse","j'ai reçu"],"examTip":"Prepare flexible phrases for the unexpected question in advance; you cannot predict it exactly, but a stock structure (opinion + reason + example) will fit almost any topic.","answerTopic":"2.2-speaking-1"},{"id":"fr-p2-2-3-0","paper":"Paper 2","module":"2.3","moduleTitle":"Celebrity culture","question":"Describe this photo of a fan taking a photo on her phone at a concert, with a singer performing on stage. Say what is happening, how the fan might feel, and give your opinion on celebrity culture.","marks":10,"command":"Describe the photo","sourcePage":null,"rubric":"","modelAnswer":"Sur la photo, une jeune fille prend une photo sur son téléphone pendant qu'un chanteur se produit sur scène. Elle a l'air très excitée. Personnellement, j'apprécie certaines célébrités pour leur talent, mais je pense que les réseaux sociaux créent une pression excessive sur les jeunes qui veulent leur ressembler.\n\n(English translation: In the photo, a young girl is taking a photo on her phone while a singer performs on stage. She looks very excited. Personally, I appreciate some celebrities for their talent, but I think social media creates excessive pressure on young people who want to look like them.)\n\nUseful phrases: elle a l'air + adjective; j'apprécie... pour...; créer une pression sur","evidence":["elle a l'air + adjective","j'apprécie... pour...","créer une pression sur"],"examTip":"Structure your description in three parts: what you see, an opinion, and a personal link — this shows range beyond simple description.","answerTopic":"2.3-speaking-0"},{"id":"fr-p2-2-3-1","paper":"Paper 2","module":"2.3","moduleTitle":"Celebrity culture","question":"Role-play: your teacher plays a French friend discussing celebrities. You must (1) name a celebrity you admire, (2) say why, and (3) answer an unexpected question about a disadvantage of fame.","marks":10,"command":"Role-play","sourcePage":null,"rubric":"","modelAnswer":"— J'admire l'actrice Marion Cotillard.\n— Je l'admire parce qu'elle est très talentueuse et elle soutient des causes importantes.\n— (Question imprévue) Je pense que l'inconvénient principal de la célébrité, c'est la perte de la vie privée.\n\n(English translation: — I admire the actress Marion Cotillard.\n— I admire her because she is very talented and supports important causes.\n— (Unexpected question) I think the main disadvantage of fame is the loss of privacy.)\n\nUseful phrases: j'admire... parce que; soutenir des causes; l'inconvénient principal","evidence":["j'admire... parce que","soutenir des causes","l'inconvénient principal"],"examTip":"Prepare flexible phrases for the unexpected question in advance; you cannot predict it exactly, but a stock structure (opinion + reason + example) will fit almost any topic.","answerTopic":"2.3-speaking-1"},{"id":"fr-p2-3-1-0","paper":"Paper 2","module":"3.1","moduleTitle":"Travel and tourism, including places of interest","question":"Describe this photo of a family on a sandy beach with a historic old town and castle visible in the background. Say what is happening, what the place might be like, and give your opinion on beach holidays.","marks":10,"command":"Describe the photo","sourcePage":null,"rubric":"","modelAnswer":"Sur la photo, je vois une famille sur une plage de sable, avec une vieille ville et un château en arrière-plan. Le temps a l'air magnifique et l'endroit semble très touristique. À mon avis, les vacances à la plage sont idéales parce qu'on peut se détendre tout en visitant des sites culturels intéressants.\n\n(English translation: In the photo, I can see a family on a sandy beach, with an old town and castle in the background. The weather looks beautiful and the place seems very touristy. In my opinion, beach holidays are ideal because you can relax while also visiting interesting cultural sites.)\n\nUseful phrases: en arrière-plan; l'endroit semble...; tout en + gerund","evidence":["en arrière-plan","l'endroit semble...","tout en + gerund"],"examTip":"Structure your description in three parts: what you see, an opinion, and a personal link — this shows range beyond simple description.","answerTopic":"3.1-speaking-0"},{"id":"fr-p2-3-1-1","paper":"Paper 2","module":"3.1","moduleTitle":"Travel and tourism, including places of interest","question":"Role-play: your teacher plays a French hotel receptionist. You must (1) say you would like to book a room, (2) ask about breakfast, and (3) answer an unexpected question about how many nights you are staying.","marks":10,"command":"Role-play","sourcePage":null,"rubric":"","modelAnswer":"— Bonjour, je voudrais réserver une chambre pour deux personnes, s'il vous plaît.\n— Est-ce que le petit-déjeuner est inclus dans le prix ?\n— (Question imprévue) Nous allons rester trois nuits, du vendredi au dimanche.\n\n(English translation: — Hello, I would like to book a room for two people, please.\n— Is breakfast included in the price?\n— (Unexpected question) We are going to stay three nights, from Friday to Sunday.)\n\nUseful phrases: je voudrais réserver; est-ce que... est inclus ?; nous allons rester","evidence":["je voudrais réserver","est-ce que... est inclus ?","nous allons rester"],"examTip":"Prepare flexible phrases for the unexpected question in advance; you cannot predict it exactly, but a stock structure (opinion + reason + example) will fit almost any topic.","answerTopic":"3.1-speaking-1"},{"id":"fr-p2-3-2-0","paper":"Paper 2","module":"3.2","moduleTitle":"Media and technology","question":"Describe this photo of two teenagers sitting on a sofa, both looking at their phones instead of talking to each other. Say what is happening, how you feel about this, and give your opinion on phone use among young people.","marks":10,"command":"Describe the photo","sourcePage":null,"rubric":"","modelAnswer":"Sur la photo, deux adolescents sont assis sur un canapé, mais ils regardent tous les deux leur téléphone au lieu de se parler. Je trouve cette situation un peu triste. À mon avis, les jeunes devraient parfois éteindre leur portable pour profiter du moment présent avec leurs amis.\n\n(English translation: In the photo, two teenagers are sitting on a sofa, but they are both looking at their phone instead of talking to each other. I find this situation a bit sad. In my opinion, young people should sometimes turn off their phone to enjoy the present moment with their friends.)\n\nUseful phrases: au lieu de + infinitive; je trouve cette situation...; devrait + infinitive","evidence":["au lieu de + infinitive","je trouve cette situation...","devrait + infinitive"],"examTip":"Structure your description in three parts: what you see, an opinion, and a personal link — this shows range beyond simple description.","answerTopic":"3.2-speaking-0"},{"id":"fr-p2-3-2-1","paper":"Paper 2","module":"3.2","moduleTitle":"Media and technology","question":"Role-play: your teacher plays a French parent discussing screen time. You must (1) say how much time you spend on your phone, (2) suggest a compromise, and (3) answer an unexpected question about why social media is useful to you.","marks":10,"command":"Role-play","sourcePage":null,"rubric":"","modelAnswer":"— Je passe environ deux heures par jour sur mon portable.\n— On pourrait fixer une limite d'une heure le soir ?\n— (Question imprévue) Les réseaux sociaux me sont utiles parce que je peux rester en contact avec mes amis qui habitent loin.\n\n(English translation: — I spend about two hours a day on my phone.\n— Could we set a one-hour limit in the evening?\n— (Unexpected question) Social media is useful to me because I can stay in touch with friends who live far away.)\n\nUseful phrases: je passe... sur mon portable; on pourrait fixer...; rester en contact avec","evidence":["je passe... sur mon portable","on pourrait fixer...","rester en contact avec"],"examTip":"Prepare flexible phrases for the unexpected question in advance; you cannot predict it exactly, but a stock structure (opinion + reason + example) will fit almost any topic.","answerTopic":"3.2-speaking-1"},{"id":"fr-p2-3-3-0","paper":"Paper 2","module":"3.3","moduleTitle":"The environment and where people live","question":"Describe this photo of three coloured recycling bins (glass, paper, plastic) outside a block of flats. Say what the photo shows, what people are doing (or should do), and give your opinion on recycling.","marks":10,"command":"Describe the photo","sourcePage":null,"rubric":"","modelAnswer":"Sur la photo, je vois trois poubelles de couleurs différentes pour le verre, le papier et le plastique, devant un immeuble. Je pense que les habitants utilisent ce système pour trier leurs déchets. À mon avis, le recyclage est essentiel parce qu'il permet de réduire la pollution et de protéger les ressources naturelles.\n\n(English translation: In the photo, I can see three different coloured bins for glass, paper and plastic, outside a block of flats. I think residents use this system to sort their waste. In my opinion, recycling is essential because it helps reduce pollution and protect natural resources.)\n\nUseful phrases: trier les déchets; il permet de + infinitive; protéger les ressources naturelles","evidence":["trier les déchets","il permet de + infinitive","protéger les ressources naturelles"],"examTip":"Structure your description in three parts: what you see, an opinion, and a personal link — this shows range beyond simple description.","answerTopic":"3.3-speaking-0"},{"id":"fr-p2-3-3-1","paper":"Paper 2","module":"3.3","moduleTitle":"The environment and where people live","question":"Role-play: your teacher plays a French local councillor discussing environmental problems. You must (1) mention an environmental problem in your area, (2) suggest a solution, and (3) answer an unexpected question about what you personally do to help the environment.","marks":10,"command":"Role-play","sourcePage":null,"rubric":"","modelAnswer":"— Il y a trop de pollution causée par les voitures dans ma ville.\n— Il faudrait développer plus de pistes cyclables et de transports en commun.\n— (Question imprévue) Personnellement, je recycle à la maison et je vais à l'école à vélo.\n\n(English translation: — There is too much pollution caused by cars in my town.\n— More cycle paths and public transport should be developed.\n— (Unexpected question) Personally, I recycle at home and I cycle to school.)\n\nUseful phrases: il y a trop de pollution; il faudrait + infinitive; je vais à l'école à vélo","evidence":["il y a trop de pollution","il faudrait + infinitive","je vais à l'école à vélo"],"examTip":"Prepare flexible phrases for the unexpected question in advance; you cannot predict it exactly, but a stock structure (opinion + reason + example) will fit almost any topic.","answerTopic":"3.3-speaking-1"}],"paper3":[{"id":"fr-p3-1-1-0","paper":"Paper 3","module":"1.1","moduleTitle":"Identity and relationships with others","question":"Reading comprehension. Read the passage and answer in English:\n\n\"Léa, 15 ans : « Mes parents se sont séparés quand j'avais dix ans. Au début, j'étais triste parce que je ne voyais plus mon père tous les jours. Maintenant, ma mère est remariée et j'ai un demi-frère que j'adore. Je passe une semaine chez mon père et une semaine chez ma mère. C'est parfois compliqué d'organiser mes affaires, mais je pense que j'ai de la chance d'avoir deux maisons pleines d'amour. »\"\n\n1. How old was Léa when her parents separated?\n2. How did she feel at first, and why?\n3. What does she say about her half-brother?\n4. What is sometimes complicated for her?\n5. What is her overall opinion about her family situation?","marks":10,"command":"Reading comprehension","sourcePage":null,"rubric":"","modelAnswer":"1. Ten years old (\"quand j'avais dix ans\").\n2. Sad, because she no longer saw her father every day (\"je ne voyais plus mon père tous les jours\").\n3. She adores him (\"j'ai un demi-frère que j'adore\").\n4. Organising her belongings between two houses (\"organiser mes affaires\").\n5. She thinks she is lucky to have two homes full of love (\"j'ai de la chance d'avoir deux maisons pleines d'amour\").","evidence":[],"examTip":"Answer using information from the passage only; quoting the relevant French phrase alongside your English answer can help you check you haven't missed detail.","answerTopic":"1.1-reading-0"},{"id":"fr-p3-1-1-1","paper":"Paper 3","module":"1.1","moduleTitle":"Identity and relationships with others","question":"Translate into English:\n\n1. Je m'entends très bien avec ma sœur jumelle.\n2. Mes parents sont divorcés depuis trois ans.\n3. Il est important d'être fidèle à ses amis.\n4. Nous nous disputons rarement, mais on se réconcilie toujours vite.","marks":10,"command":"Translate into English","sourcePage":null,"rubric":"","modelAnswer":"1. I get on very well with my twin sister.\n2. My parents have been divorced for three years.\n3. It is important to be loyal to your friends.\n4. We rarely argue, but we always make up quickly.","evidence":[],"examTip":"Translate the full meaning of each sentence into natural English rather than word-for-word; check tenses (perfect/present) carry across accurately.","answerTopic":"1.1-translate-en-0"},{"id":"fr-p3-1-2-0","paper":"Paper 3","module":"1.2","moduleTitle":"Healthy living and lifestyle","question":"Reading comprehension. Read the passage and answer in English:\n\n\"Beaucoup de jeunes Français mangent trop de malbouffe à cause du prix bas et de la rapidité. Cependant, de plus en plus de lycées proposent des cantines avec des menus équilibrés, incluant des fruits et des légumes frais. Une étude récente montre que les adolescents qui font du sport régulièrement dorment mieux et sont moins stressés avant les examens. Les médecins conseillent de limiter les écrans le soir pour améliorer le sommeil.\"\n\n1. Why do many young French people eat a lot of junk food, according to the text?\n2. What are more schools now offering?\n3. What does a recent study show about teenagers who do regular sport?\n4. What do doctors recommend in the evening, and why?","marks":10,"command":"Reading comprehension","sourcePage":null,"rubric":"","modelAnswer":"1. Because of the low price and the speed (\"à cause du prix bas et de la rapidité\").\n2. Canteens with balanced menus including fresh fruit and vegetables (\"des menus équilibrés, incluant des fruits et des légumes frais\").\n3. They sleep better and are less stressed before exams (\"dorment mieux et sont moins stressés avant les examens\").\n4. Limiting screens, to improve sleep (\"limiter les écrans le soir pour améliorer le sommeil\").","evidence":[],"examTip":"Answer using information from the passage only; quoting the relevant French phrase alongside your English answer can help you check you haven't missed detail.","answerTopic":"1.2-reading-0"},{"id":"fr-p3-1-2-1","paper":"Paper 3","module":"1.2","moduleTitle":"Healthy living and lifestyle","question":"Translate into English:\n\n1. Il ne faut pas fumer parce que c'est mauvais pour la santé.\n2. Je bois beaucoup d'eau tous les jours.\n3. Mon père a arrêté de manger de la viande rouge.\n4. On devrait faire plus d'exercice pour rester en forme.","marks":10,"command":"Translate into English","sourcePage":null,"rubric":"","modelAnswer":"1. You must not smoke because it is bad for your health.\n2. I drink a lot of water every day.\n3. My father stopped eating red meat.\n4. We should do more exercise to stay fit.","evidence":[],"examTip":"Translate the full meaning of each sentence into natural English rather than word-for-word; check tenses (perfect/present) carry across accurately.","answerTopic":"1.2-translate-en-0"},{"id":"fr-p3-1-3-0","paper":"Paper 3","module":"1.3","moduleTitle":"Education and work","question":"Reading comprehension. Read the passage and answer in English:\n\n\"En France, beaucoup de collégiens trouvent la pression des examens difficile à gérer, surtout avant le brevet. Certains lycées offrent maintenant des ateliers pour aider les élèves à mieux gérer leur stress. De plus, le stage en entreprise de troisième permet aux élèves de découvrir le monde du travail avant de choisir leur orientation. Après le lycée, de nombreux jeunes choisissent entre l'université, un BTS ou un apprentissage.\"\n\n1. What do many middle-school students in France find difficult to manage?\n2. What do some schools now offer, and why?\n3. What does the Year 9 (troisième) work placement allow students to do?\n4. What three options do many young people choose between after lycée?","marks":10,"command":"Reading comprehension","sourcePage":null,"rubric":"","modelAnswer":"1. Exam pressure, especially before the brevet (\"la pression des examens difficile à gérer, surtout avant le brevet\").\n2. Workshops to help students manage their stress better (\"des ateliers pour aider les élèves à mieux gérer leur stress\").\n3. Discover the world of work before choosing their path (\"découvrir le monde du travail avant de choisir leur orientation\").\n4. University, a BTS (vocational diploma), or an apprenticeship (\"l'université, un BTS ou un apprentissage\").","evidence":[],"examTip":"Answer using information from the passage only; quoting the relevant French phrase alongside your English answer can help you check you haven't missed detail.","answerTopic":"1.3-reading-0"},{"id":"fr-p3-1-3-1","paper":"Paper 3","module":"1.3","moduleTitle":"Education and work","question":"Translate into English:\n\n1. Ma matière préférée, c'est l'histoire-géographie.\n2. L'année prochaine, je vais passer mes examens.\n3. J'ai fait un stage dans un bureau pendant deux semaines.\n4. Plus tard, je voudrais devenir ingénieur.","marks":10,"command":"Translate into English","sourcePage":null,"rubric":"","modelAnswer":"1. My favourite subject is history-geography.\n2. Next year, I am going to sit my exams.\n3. I did a work placement in an office for two weeks.\n4. Later, I would like to become an engineer.","evidence":[],"examTip":"Translate the full meaning of each sentence into natural English rather than word-for-word; check tenses (perfect/present) carry across accurately.","answerTopic":"1.3-translate-en-0"},{"id":"fr-p3-2-1-0","paper":"Paper 3","module":"2.1","moduleTitle":"Free-time activities","question":"Reading comprehension. Read the passage and answer in English:\n\n\"Selon un sondage récent, les jeunes Français passent en moyenne deux heures par jour sur leurs loisirs numériques, comme les jeux vidéo et les réseaux sociaux. Cependant, beaucoup pratiquent aussi des activités traditionnelles : la lecture reste populaire chez 40% des adolescents, et le sport collectif, comme le foot ou le basket, attire de nombreux jeunes le week-end. Les associations locales proposent souvent des activités gratuites pendant les vacances scolaires.\"\n\n1. How much time do young French people spend on digital leisure activities per day, on average?\n2. What two digital activities are mentioned?\n3. What percentage of teenagers say reading remains popular?\n4. What do local associations often offer during school holidays?","marks":10,"command":"Reading comprehension","sourcePage":null,"rubric":"","modelAnswer":"1. Two hours a day on average (\"en moyenne deux heures par jour\").\n2. Video games and social media (\"les jeux vidéo et les réseaux sociaux\").\n3. 40% (\"la lecture reste populaire chez 40% des adolescents\").\n4. Free activities during school holidays (\"des activités gratuites pendant les vacances scolaires\").","evidence":[],"examTip":"Answer using information from the passage only; quoting the relevant French phrase alongside your English answer can help you check you haven't missed detail.","answerTopic":"2.1-reading-0"},{"id":"fr-p3-2-1-1","paper":"Paper 3","module":"2.1","moduleTitle":"Free-time activities","question":"Translate into English:\n\n1. J'aime jouer aux jeux vidéo avec mes amis.\n2. Le week-end dernier, je suis allé(e) au cinéma.\n3. Elle fait du shopping tous les samedis.\n4. Nous préférons regarder un film à la maison.","marks":10,"command":"Translate into English","sourcePage":null,"rubric":"","modelAnswer":"1. I like playing video games with my friends.\n2. Last weekend, I went to the cinema.\n3. She goes shopping every Saturday.\n4. We prefer to watch a film at home.","evidence":[],"examTip":"Translate the full meaning of each sentence into natural English rather than word-for-word; check tenses (perfect/present) carry across accurately.","answerTopic":"2.1-translate-en-0"},{"id":"fr-p3-2-2-0","paper":"Paper 3","module":"2.2","moduleTitle":"Customs, festivals and celebrations","question":"Reading comprehension. Read the passage and answer in English:\n\n\"Le Carnaval de Nice est l'un des festivals les plus célèbres de France. Chaque année, en février, des milliers de visiteurs viennent admirer les chars décorés et les batailles de fleurs. Cette tradition existe depuis le Moyen Âge et attire maintenant plus d'un million de spectateurs. Les habitants adorent se déguiser et participer aux défilés dans les rues de la ville.\"\n\n1. What is described as one of the most famous festivals in France?\n2. When does it take place each year?\n3. What do thousands of visitors come to admire?\n4. How many spectators does the festival now attract?","marks":10,"command":"Reading comprehension","sourcePage":null,"rubric":"","modelAnswer":"1. The Nice Carnival (\"Le Carnaval de Nice\").\n2. In February (\"chaque année, en février\").\n3. Decorated floats and flower battles (\"les chars décorés et les batailles de fleurs\").\n4. More than a million spectators (\"plus d'un million de spectateurs\").","evidence":[],"examTip":"Answer using information from the passage only; quoting the relevant French phrase alongside your English answer can help you check you haven't missed detail.","answerTopic":"2.2-reading-0"},{"id":"fr-p3-2-2-1","paper":"Paper 3","module":"2.2","moduleTitle":"Customs, festivals and celebrations","question":"Translate into English:\n\n1. Chaque année, nous fêtons Noël en famille.\n2. L'été dernier, j'ai assisté à un festival de musique.\n3. On a vu un magnifique feu d'artifice.\n4. C'est une tradition importante dans ma culture.","marks":10,"command":"Translate into English","sourcePage":null,"rubric":"","modelAnswer":"1. Every year, we celebrate Christmas as a family.\n2. Last summer, I attended a music festival.\n3. We saw magnificent fireworks.\n4. It is an important tradition in my culture.","evidence":[],"examTip":"Translate the full meaning of each sentence into natural English rather than word-for-word; check tenses (perfect/present) carry across accurately.","answerTopic":"2.2-translate-en-0"},{"id":"fr-p3-2-3-0","paper":"Paper 3","module":"2.3","moduleTitle":"Celebrity culture","question":"Reading comprehension. Read the passage and answer in English:\n\n\"Selon un sondage, 60% des adolescents français suivent au moins un influenceur sur les réseaux sociaux. Si certains influenceurs partagent des conseils utiles, d'autres critiques estiment qu'ils donnent une image irréaliste de la vie. Les experts conseillent aux jeunes de garder un esprit critique face au contenu en ligne et de se rappeler que les photos sont souvent retouchées.\"\n\n1. What percentage of French teenagers follow at least one influencer?\n2. What do some influencers share, according to the text?\n3. What do critics say some influencers do?\n4. What do experts advise young people to remember?","marks":10,"command":"Reading comprehension","sourcePage":null,"rubric":"","modelAnswer":"1. 60% (\"60% des adolescents français suivent au moins un influenceur\").\n2. Useful advice (\"des conseils utiles\").\n3. Give an unrealistic image of life (\"ils donnent une image irréaliste de la vie\").\n4. That photos are often edited/retouched (\"les photos sont souvent retouchées\").","evidence":[],"examTip":"Answer using information from the passage only; quoting the relevant French phrase alongside your English answer can help you check you haven't missed detail.","answerTopic":"2.3-reading-0"},{"id":"fr-p3-2-3-1","paper":"Paper 3","module":"2.3","moduleTitle":"Celebrity culture","question":"Translate into English:\n\n1. J'admire beaucoup cette chanteuse parce qu'elle est généreuse.\n2. Certains influenceurs gagnent beaucoup d'argent.\n3. La célébrité a des avantages et des inconvénients.\n4. Il est important de garder un esprit critique.","marks":10,"command":"Translate into English","sourcePage":null,"rubric":"","modelAnswer":"1. I really admire this singer because she is generous.\n2. Some influencers earn a lot of money.\n3. Fame has advantages and disadvantages.\n4. It is important to keep a critical mind.","evidence":[],"examTip":"Translate the full meaning of each sentence into natural English rather than word-for-word; check tenses (perfect/present) carry across accurately.","answerTopic":"2.3-translate-en-0"},{"id":"fr-p3-3-1-0","paper":"Paper 3","module":"3.1","moduleTitle":"Travel and tourism, including places of interest","question":"Reading comprehension. Read the passage and answer in English:\n\n\"Paris attire chaque année des millions de touristes du monde entier. Parmi les endroits les plus visités, on trouve la Tour Eiffel, le musée du Louvre et la cathédrale Notre-Dame. Beaucoup de visiteurs se déplacent en métro parce que c'est rapide et pas cher. L'office de tourisme recommande aussi de découvrir les petits quartiers moins connus pour éviter la foule et vivre une expérience plus authentique.\"\n\n1. How many tourists does Paris attract each year, roughly?\n2. Name two of the most visited places mentioned.\n3. How do many visitors get around, and why?\n4. What does the tourist office also recommend, and why?","marks":10,"command":"Reading comprehension","sourcePage":null,"rubric":"","modelAnswer":"1. Millions of tourists from around the world (\"des millions de touristes du monde entier\").\n2. The Eiffel Tower and the Louvre museum (accept Notre-Dame cathedral too) (\"la Tour Eiffel, le musée du Louvre\").\n3. By metro, because it is fast and not expensive (\"en métro parce que c'est rapide et pas cher\").\n4. Discover lesser-known areas, to avoid crowds and have a more authentic experience (\"éviter la foule et vivre une expérience plus authentique\").","evidence":[],"examTip":"Answer using information from the passage only; quoting the relevant French phrase alongside your English answer can help you check you haven't missed detail.","answerTopic":"3.1-reading-0"},{"id":"fr-p3-3-1-1","paper":"Paper 3","module":"3.1","moduleTitle":"Travel and tourism, including places of interest","question":"Translate into English:\n\n1. L'été dernier, je suis allé(e) en vacances en France.\n2. Nous avons réservé un hôtel près de la plage.\n3. Il faisait beau pendant tout le séjour.\n4. J'aimerais visiter l'Italie l'année prochaine.","marks":10,"command":"Translate into English","sourcePage":null,"rubric":"","modelAnswer":"1. Last summer, I went on holiday to France.\n2. We booked a hotel near the beach.\n3. The weather was nice during the whole stay.\n4. I would like to visit Italy next year.","evidence":[],"examTip":"Translate the full meaning of each sentence into natural English rather than word-for-word; check tenses (perfect/present) carry across accurately.","answerTopic":"3.1-translate-en-0"},{"id":"fr-p3-3-2-0","paper":"Paper 3","module":"3.2","moduleTitle":"Media and technology","question":"Reading comprehension. Read the passage and answer in English:\n\n\"Une étude montre que 85% des adolescents français possèdent un smartphone. Si les réseaux sociaux permettent de rester en contact avec des amis, certains experts s'inquiètent de leurs effets sur le sommeil et la concentration. Plusieurs écoles ont donc interdit l'usage des portables pendant les cours. Les parents sont encouragés à discuter régulièrement avec leurs enfants des dangers d'Internet, comme le cyberharcèlement.\"\n\n1. What percentage of French teenagers own a smartphone?\n2. What do social media allow people to do, according to the text?\n3. What are some experts worried about?\n4. What have several schools done, and why?\n5. What danger of the internet is mentioned at the end?","marks":10,"command":"Reading comprehension","sourcePage":null,"rubric":"","modelAnswer":"1. 85% (\"85% des adolescents français possèdent un smartphone\").\n2. Stay in touch with friends (\"rester en contact avec des amis\").\n3. Their effects on sleep and concentration (\"leurs effets sur le sommeil et la concentration\").\n4. Banned phone use during lessons (\"interdit l'usage des portables pendant les cours\").\n5. Cyberbullying (\"le cyberharcèlement\").","evidence":[],"examTip":"Answer using information from the passage only; quoting the relevant French phrase alongside your English answer can help you check you haven't missed detail.","answerTopic":"3.2-reading-0"},{"id":"fr-p3-3-2-1","paper":"Paper 3","module":"3.2","moduleTitle":"Media and technology","question":"Translate into English:\n\n1. Je passe trop de temps sur les réseaux sociaux.\n2. Il est important de protéger sa vie privée en ligne.\n3. Mes parents limitent mon temps d'écran le soir.\n4. La technologie a des avantages et des inconvénients.","marks":10,"command":"Translate into English","sourcePage":null,"rubric":"","modelAnswer":"1. I spend too much time on social media.\n2. It is important to protect your privacy online.\n3. My parents limit my screen time in the evening.\n4. Technology has advantages and disadvantages.","evidence":[],"examTip":"Translate the full meaning of each sentence into natural English rather than word-for-word; check tenses (perfect/present) carry across accurately.","answerTopic":"3.2-translate-en-0"},{"id":"fr-p3-3-3-0","paper":"Paper 3","module":"3.3","moduleTitle":"The environment and where people live","question":"Reading comprehension. Read the passage and answer in English:\n\n\"De nombreuses villes françaises essaient de réduire la pollution en développant les transports en commun et les pistes cyclables. À Strasbourg, par exemple, le tramway est gratuit pour les habitants certains jours de l'année afin d'encourager son utilisation. Par ailleurs, la ville a planté des milliers d'arbres pour améliorer la qualité de l'air. Les habitants sont aussi invités à participer à des ateliers sur le recyclage et la réduction des déchets.\"\n\n1. What are many French towns trying to reduce?\n2. What is free in Strasbourg on certain days, and why?\n3. What has the city planted, and for what purpose?\n4. What are residents invited to take part in?","marks":10,"command":"Reading comprehension","sourcePage":null,"rubric":"","modelAnswer":"1. Pollution (\"réduire la pollution\").\n2. The tram, to encourage its use (\"le tramway est gratuit... afin d'encourager son utilisation\").\n3. Thousands of trees, to improve air quality (\"planté des milliers d'arbres pour améliorer la qualité de l'air\").\n4. Workshops on recycling and reducing waste (\"des ateliers sur le recyclage et la réduction des déchets\").","evidence":[],"examTip":"Answer using information from the passage only; quoting the relevant French phrase alongside your English answer can help you check you haven't missed detail.","answerTopic":"3.3-reading-0"},{"id":"fr-p3-3-3-1","paper":"Paper 3","module":"3.3","moduleTitle":"The environment and where people live","question":"Translate into English:\n\n1. Il faut protéger l'environnement pour les générations futures.\n2. Nous recyclons le verre et le papier à la maison.\n3. La pollution est un problème grave dans les grandes villes.\n4. J'habite dans un petit village calme à la campagne.","marks":10,"command":"Translate into English","sourcePage":null,"rubric":"","modelAnswer":"1. We must protect the environment for future generations.\n2. We recycle glass and paper at home.\n3. Pollution is a serious problem in big cities.\n4. I live in a small, quiet village in the countryside.","evidence":[],"examTip":"Translate the full meaning of each sentence into natural English rather than word-for-word; check tenses (perfect/present) carry across accurately.","answerTopic":"3.3-translate-en-0"}],"paper4":[{"id":"fr-p4-1-1-0","paper":"Paper 4","module":"1.1","moduleTitle":"Identity and relationships with others","question":"Écrivez un article sur vos relations avec votre famille et vos amis. Vous devez mentionner :\n• une description de votre famille\n• votre relation avec un ami ou un membre de la famille\n• votre opinion sur l'importance de la famille, avec une raison\n• quelque chose que vous avez fait récemment en famille.","marks":10,"command":"Write in French","sourcePage":null,"rubric":"","modelAnswer":"Dans ma famille, nous sommes cinq : mes parents, mes deux frères et moi. Je m'entends très bien avec ma mère parce qu'elle est toujours de bon conseil. Mon meilleur ami, Nathan, est loyal et drôle, et je lui fais totalement confiance. À mon avis, la famille est la chose la plus importante dans la vie parce qu'elle nous soutient dans les moments difficiles. Le week-end dernier, nous sommes allés chez mes grands-parents et nous avons préparé un grand repas ensemble. C'était un moment très agréable.\n\n(English translation: In my family there are five of us: my parents, my two brothers and me. I get on very well with my mother because she always gives good advice. My best friend, Nathan, is loyal and funny, and I trust him completely. In my opinion, family is the most important thing in life because it supports us in difficult times. Last weekend we went to my grandparents' house and we prepared a big meal together. It was a very enjoyable moment.)","evidence":[],"examTip":"Cover every bullet point, use at least two tenses (e.g. perfect + near future) and always justify opinions with parce que/car to access the top marks.","answerTopic":"1.1-writing-0"},{"id":"fr-p4-1-1-1","paper":"Paper 4","module":"1.1","moduleTitle":"Identity and relationships with others","question":"Translate into French:\n\n1. I get on well with my parents.\n2. My best friend is very loyal.\n3. Last year, we moved house.\n4. In my opinion, friendship is more important than money.","marks":10,"command":"Translate into French","sourcePage":null,"rubric":"","modelAnswer":"1. Je m'entends bien avec mes parents.\n2. Mon meilleur ami/Ma meilleure amie est très fidèle.\n3. L'année dernière, nous avons déménagé.\n4. À mon avis, l'amitié est plus importante que l'argent.","evidence":[],"examTip":"Check verb endings and adjective agreement carefully; accurate grammar scores marks even if your vocabulary choice is simple.","answerTopic":"1.1-translate-fr-0"},{"id":"fr-p4-1-2-0","paper":"Paper 4","module":"1.2","moduleTitle":"Healthy living and lifestyle","question":"Écrivez un article sur la vie saine. Vous devez mentionner :\n• ce que vous faites pour rester en forme\n• votre opinion sur l'alimentation équilibrée, avec une raison\n• un changement que vous avez fait récemment\n• un conseil pour les jeunes qui veulent être en meilleure santé.","marks":10,"command":"Write in French","sourcePage":null,"rubric":"","modelAnswer":"Pour rester en forme, je fais de la natation deux fois par semaine et j'essaie de manger équilibré. À mon avis, une alimentation saine est essentielle parce qu'elle donne de l'énergie et améliore la concentration à l'école. Le mois dernier, j'ai décidé d'arrêter de boire des boissons sucrées, et je me sens beaucoup mieux depuis. Je conseille aux jeunes de dormir au moins huit heures par nuit et de limiter le temps passé devant les écrans.\n\n(English translation: To stay fit, I go swimming twice a week and I try to eat healthily. In my opinion, a healthy diet is essential because it gives you energy and improves concentration at school. Last month, I decided to stop drinking sugary drinks, and I have felt much better since. I advise young people to sleep at least eight hours a night and limit screen time.)","evidence":[],"examTip":"Cover every bullet point, use at least two tenses (e.g. perfect + near future) and always justify opinions with parce que/car to access the top marks.","answerTopic":"1.2-writing-0"},{"id":"fr-p4-1-2-1","paper":"Paper 4","module":"1.2","moduleTitle":"Healthy living and lifestyle","question":"Translate into French:\n\n1. I try to eat a balanced diet every day.\n2. You should not drink too much coffee.\n3. Last year, I started doing yoga.\n4. In my opinion, sleep is as important as exercise.","marks":10,"command":"Translate into French","sourcePage":null,"rubric":"","modelAnswer":"1. J'essaie de manger équilibré tous les jours.\n2. Tu ne devrais pas boire trop de café.\n3. L'année dernière, j'ai commencé à faire du yoga.\n4. À mon avis, le sommeil est aussi important que l'exercice.","evidence":[],"examTip":"Check verb endings and adjective agreement carefully; accurate grammar scores marks even if your vocabulary choice is simple.","answerTopic":"1.2-translate-fr-0"},{"id":"fr-p4-1-3-0","paper":"Paper 4","module":"1.3","moduleTitle":"Education and work","question":"Écrivez un article sur l'école et vos projets d'avenir. Vous devez mentionner :\n• votre matière préférée et pourquoi\n• un stage ou un petit boulot que vous avez fait\n• votre opinion sur la pression des examens, avec une raison\n• ce que vous allez faire après le lycée.","marks":10,"command":"Write in French","sourcePage":null,"rubric":"","modelAnswer":"Ma matière préférée est l'espagnol parce que j'adore découvrir de nouvelles cultures. L'été dernier, j'ai fait un stage dans une école primaire où j'ai aidé les enfants avec la lecture. À mon avis, la pression des examens est parfois trop forte parce que beaucoup d'élèves deviennent stressés et fatigués. Après le lycée, je vais faire des études de langues à l'université, et plus tard, j'aimerais devenir professeur.\n\n(English translation: My favourite subject is Spanish because I love discovering new cultures. Last summer, I did a placement in a primary school where I helped children with reading. In my opinion, exam pressure is sometimes too strong because many students become stressed and tired. After lycée, I am going to study languages at university, and later I would like to become a teacher.)","evidence":[],"examTip":"Cover every bullet point, use at least two tenses (e.g. perfect + near future) and always justify opinions with parce que/car to access the top marks.","answerTopic":"1.3-writing-0"},{"id":"fr-p4-1-3-1","paper":"Paper 4","module":"1.3","moduleTitle":"Education and work","question":"Translate into French:\n\n1. My favourite subject is French because the teacher is very kind.\n2. Next year, I am going to do a work placement.\n3. I earn money with a part-time job at the weekend.\n4. Later, I would like to study medicine.","marks":10,"command":"Translate into French","sourcePage":null,"rubric":"","modelAnswer":"1. Ma matière préférée est le français parce que le professeur est très gentil.\n2. L'année prochaine, je vais faire un stage en entreprise.\n3. Je gagne de l'argent avec un petit boulot le week-end.\n4. Plus tard, je voudrais faire des études de médecine.","evidence":[],"examTip":"Check verb endings and adjective agreement carefully; accurate grammar scores marks even if your vocabulary choice is simple.","answerTopic":"1.3-translate-fr-0"},{"id":"fr-p4-2-1-0","paper":"Paper 4","module":"2.1","moduleTitle":"Free-time activities","question":"Écrivez un article sur vos loisirs. Vous devez mentionner :\n• ce que vous faites pendant votre temps libre\n• une activité que vous avez faite récemment\n• votre opinion sur l'importance des loisirs, avec une raison\n• une activité que vous aimeriez essayer à l'avenir.","marks":10,"command":"Write in French","sourcePage":null,"rubric":"","modelAnswer":"Pendant mon temps libre, j'aime faire du sport et sortir avec mes amis. Le mois dernier, je suis allé(e) à un concert avec ma meilleure amie, et c'était une soirée inoubliable. À mon avis, les loisirs sont essentiels parce qu'ils permettent de réduire le stress après une longue journée à l'école. À l'avenir, j'aimerais essayer l'escalade parce que ça a l'air passionnant.\n\n(English translation: In my free time, I like doing sport and going out with my friends. Last month, I went to a concert with my best friend, and it was an unforgettable evening. In my opinion, hobbies are essential because they help reduce stress after a long day at school. In the future, I would like to try climbing because it looks exciting.)","evidence":[],"examTip":"Cover every bullet point, use at least two tenses (e.g. perfect + near future) and always justify opinions with parce que/car to access the top marks.","answerTopic":"2.1-writing-0"},{"id":"fr-p4-2-1-1","paper":"Paper 4","module":"2.1","moduleTitle":"Free-time activities","question":"Translate into French:\n\n1. I spend my free time reading and playing sport.\n2. Last weekend, we went shopping in town.\n3. He prefers playing video games to watching television.\n4. In the future, I would like to learn to play the guitar.","marks":10,"command":"Translate into French","sourcePage":null,"rubric":"","modelAnswer":"1. Je passe mon temps libre à lire et à faire du sport.\n2. Le week-end dernier, nous sommes allé(e)s faire du shopping en ville.\n3. Il préfère jouer aux jeux vidéo plutôt que regarder la télévision.\n4. À l'avenir, je voudrais apprendre à jouer de la guitare.","evidence":[],"examTip":"Check verb endings and adjective agreement carefully; accurate grammar scores marks even if your vocabulary choice is simple.","answerTopic":"2.1-translate-fr-0"},{"id":"fr-p4-2-2-0","paper":"Paper 4","module":"2.2","moduleTitle":"Customs, festivals and celebrations","question":"Écrivez un article sur une fête ou une tradition que vous aimez. Vous devez mentionner :\n• une description de cette fête\n• ce que vous avez fait l'année dernière\n• votre opinion sur l'importance des traditions, avec une raison\n• ce que vous allez faire pour la prochaine occasion.","marks":10,"command":"Write in French","sourcePage":null,"rubric":"","modelAnswer":"La fête que je préfère est mon anniversaire parce que toute ma famille se réunit pour célébrer. L'année dernière, j'ai organisé une fête avec mes amis et nous avons dansé toute la soirée. À mon avis, les traditions sont importantes parce qu'elles renforcent les liens familiaux et créent des souvenirs inoubliables. L'année prochaine, je vais inviter aussi mes amis d'enfance pour rendre la fête encore plus spéciale.\n\n(English translation: The celebration I prefer is my birthday because my whole family gets together to celebrate. Last year, I organised a party with my friends and we danced all evening. In my opinion, traditions are important because they strengthen family bonds and create unforgettable memories. Next year, I am going to invite my childhood friends too, to make the celebration even more special.)","evidence":[],"examTip":"Cover every bullet point, use at least two tenses (e.g. perfect + near future) and always justify opinions with parce que/car to access the top marks.","answerTopic":"2.2-writing-0"},{"id":"fr-p4-2-2-1","paper":"Paper 4","module":"2.2","moduleTitle":"Customs, festivals and celebrations","question":"Translate into French:\n\n1. My family celebrates Christmas together every year.\n2. Last year, we watched the fireworks in town.\n3. This tradition is very important to me.\n4. Next year, I am going to organise a big celebration.","marks":10,"command":"Translate into French","sourcePage":null,"rubric":"","modelAnswer":"1. Ma famille fête Noël ensemble tous les ans.\n2. L'année dernière, nous avons regardé les feux d'artifice en ville.\n3. Cette tradition est très importante pour moi.\n4. L'année prochaine, je vais organiser une grande fête.","evidence":[],"examTip":"Check verb endings and adjective agreement carefully; accurate grammar scores marks even if your vocabulary choice is simple.","answerTopic":"2.2-translate-fr-0"},{"id":"fr-p4-2-3-0","paper":"Paper 4","module":"2.3","moduleTitle":"Celebrity culture","question":"Écrivez un article sur la culture des célébrités. Vous devez mentionner :\n• une célébrité que vous admirez et pourquoi\n• votre opinion sur les avantages de la célébrité, avec une raison\n• votre opinion sur les inconvénients de la célébrité, avec une raison\n• l'influence des réseaux sociaux sur les jeunes.","marks":10,"command":"Write in French","sourcePage":null,"rubric":"","modelAnswer":"J'admire l'acteur Omar Sy parce qu'il est très talentueux et généreux ; il soutient plusieurs associations caritatives. À mon avis, l'avantage principal de la célébrité, c'est la possibilité d'inspirer les autres et de changer les choses positivement. Cependant, l'inconvénient, c'est la perte de la vie privée et la pression constante des médias. De plus, je pense que les réseaux sociaux influencent beaucoup les jeunes, qui comparent parfois leur vie à celle des célébrités.\n\n(English translation: I admire the actor Omar Sy because he is very talented and generous; he supports several charities. In my opinion, the main advantage of fame is the possibility of inspiring others and changing things positively. However, the disadvantage is the loss of privacy and the constant pressure from the media. Moreover, I think social media greatly influences young people, who sometimes compare their life to that of celebrities.)","evidence":[],"examTip":"Cover every bullet point, use at least two tenses (e.g. perfect + near future) and always justify opinions with parce que/car to access the top marks.","answerTopic":"2.3-writing-0"},{"id":"fr-p4-2-3-1","paper":"Paper 4","module":"2.3","moduleTitle":"Celebrity culture","question":"Translate into French:\n\n1. I admire this actor because he is very generous.\n2. Fame brings advantages and disadvantages.\n3. Some celebrities lose their privacy.\n4. In my opinion, social media influences young people too much.","marks":10,"command":"Translate into French","sourcePage":null,"rubric":"","modelAnswer":"1. J'admire cet acteur parce qu'il est très généreux.\n2. La célébrité apporte des avantages et des inconvénients.\n3. Certaines célébrités perdent leur vie privée.\n4. À mon avis, les réseaux sociaux influencent trop les jeunes.","evidence":[],"examTip":"Check verb endings and adjective agreement carefully; accurate grammar scores marks even if your vocabulary choice is simple.","answerTopic":"2.3-translate-fr-0"},{"id":"fr-p4-3-1-0","paper":"Paper 4","module":"3.1","moduleTitle":"Travel and tourism, including places of interest","question":"Écrivez un article sur les vacances. Vous devez mentionner :\n• où vous êtes allé(e) en vacances l'année dernière\n• ce que vous avez fait pendant le séjour\n• votre opinion sur l'importance de voyager, avec une raison\n• où vous aimeriez voyager à l'avenir.","marks":10,"command":"Write in French","sourcePage":null,"rubric":"","modelAnswer":"L'année dernière, je suis allé(e) en vacances en Italie avec mes parents. Nous avons visité beaucoup de monuments historiques et nous avons goûté des plats délicieux. À mon avis, voyager est très enrichissant parce que ça permet de découvrir de nouvelles cultures et d'améliorer ses langues. À l'avenir, j'aimerais visiter le Japon parce que la culture m'intéresse énormément.\n\n(English translation: Last year, I went on holiday to Italy with my parents. We visited lots of historic monuments and tasted delicious food. In my opinion, travelling is very enriching because it allows you to discover new cultures and improve your languages. In the future, I would like to visit Japan because the culture interests me enormously.)","evidence":[],"examTip":"Cover every bullet point, use at least two tenses (e.g. perfect + near future) and always justify opinions with parce que/car to access the top marks.","answerTopic":"3.1-writing-0"},{"id":"fr-p4-3-1-1","paper":"Paper 4","module":"3.1","moduleTitle":"Travel and tourism, including places of interest","question":"Translate into French:\n\n1. Last year, we went on holiday to Portugal.\n2. We stayed in a hotel near the old town.\n3. The weather was beautiful every day.\n4. In the future, I would like to travel abroad more.","marks":10,"command":"Translate into French","sourcePage":null,"rubric":"","modelAnswer":"1. L'année dernière, nous sommes allé(e)s en vacances au Portugal.\n2. Nous sommes resté(e)s dans un hôtel près de la vieille ville.\n3. Il faisait beau tous les jours.\n4. À l'avenir, je voudrais voyager davantage à l'étranger.","evidence":[],"examTip":"Check verb endings and adjective agreement carefully; accurate grammar scores marks even if your vocabulary choice is simple.","answerTopic":"3.1-translate-fr-0"},{"id":"fr-p4-3-2-0","paper":"Paper 4","module":"3.2","moduleTitle":"Media and technology","question":"Écrivez un article sur la technologie et les réseaux sociaux. Vous devez mentionner :\n• comment vous utilisez votre portable\n• les avantages des réseaux sociaux, avec un exemple\n• les inconvénients, avec une raison\n• un conseil pour les jeunes qui utilisent trop Internet.","marks":10,"command":"Write in French","sourcePage":null,"rubric":"","modelAnswer":"J'utilise mon portable principalement pour communiquer avec mes amis et pour faire des recherches pour l'école. D'un côté, les réseaux sociaux sont pratiques parce qu'ils permettent de rester en contact facilement, par exemple avec ma famille à l'étranger. D'un autre côté, je pense qu'ils peuvent créer une dépendance et nuire à la concentration. Je conseille aux jeunes de fixer des limites de temps et d'éteindre leur portable avant de dormir.\n\n(English translation: I use my phone mainly to communicate with my friends and to do research for school. On one hand, social media is practical because it lets you stay in touch easily, for example with my family abroad. On the other hand, I think it can create addiction and harm concentration. I advise young people to set time limits and turn off their phone before sleeping.)","evidence":[],"examTip":"Cover every bullet point, use at least two tenses (e.g. perfect + near future) and always justify opinions with parce que/car to access the top marks.","answerTopic":"3.2-writing-0"},{"id":"fr-p4-3-2-1","paper":"Paper 4","module":"3.2","moduleTitle":"Media and technology","question":"Translate into French:\n\n1. I use my phone to communicate with my friends.\n2. Social media has advantages and disadvantages.\n3. It is important to protect your personal information.\n4. You should limit your screen time in the evening.","marks":10,"command":"Translate into French","sourcePage":null,"rubric":"","modelAnswer":"1. J'utilise mon portable pour communiquer avec mes amis.\n2. Les réseaux sociaux ont des avantages et des inconvénients.\n3. Il est important de protéger ses informations personnelles.\n4. Tu devrais limiter ton temps d'écran le soir.","evidence":[],"examTip":"Check verb endings and adjective agreement carefully; accurate grammar scores marks even if your vocabulary choice is simple.","answerTopic":"3.2-translate-fr-0"},{"id":"fr-p4-3-3-0","paper":"Paper 4","module":"3.3","moduleTitle":"The environment and where people live","question":"Écrivez un article sur l'environnement et votre ville ou village. Vous devez mentionner :\n• une description de l'endroit où vous habitez\n• ce que vous faites pour protéger l'environnement\n• votre opinion sur un problème environnemental, avec une raison\n• une solution que les gens devraient adopter à l'avenir.","marks":10,"command":"Write in French","sourcePage":null,"rubric":"","modelAnswer":"J'habite dans une grande ville où il y a beaucoup de circulation et de pollution. Pour protéger l'environnement, je recycle à la maison et j'essaie de prendre les transports en commun au lieu de la voiture. À mon avis, le réchauffement climatique est le problème le plus sérieux de notre époque parce qu'il menace la planète entière. À l'avenir, je pense que tout le monde devrait réduire sa consommation de plastique et utiliser plus d'énergies renouvelables.\n\n(English translation: I live in a big city where there is a lot of traffic and pollution. To protect the environment, I recycle at home and try to take public transport instead of the car. In my opinion, global warming is the most serious problem of our time because it threatens the whole planet. In the future, I think everyone should reduce their plastic consumption and use more renewable energy.)","evidence":[],"examTip":"Cover every bullet point, use at least two tenses (e.g. perfect + near future) and always justify opinions with parce que/car to access the top marks.","answerTopic":"3.3-writing-0"},{"id":"fr-p4-3-3-1","paper":"Paper 4","module":"3.3","moduleTitle":"The environment and where people live","question":"Translate into French:\n\n1. I live in a small town near the mountains.\n2. We must recycle more to protect the planet.\n3. Climate change is a very serious problem.\n4. In the future, we should use less plastic.","marks":10,"command":"Translate into French","sourcePage":null,"rubric":"","modelAnswer":"1. J'habite dans une petite ville près des montagnes.\n2. Il faut recycler davantage pour protéger la planète.\n3. Le réchauffement climatique est un problème très grave.\n4. À l'avenir, nous devrions utiliser moins de plastique.","evidence":[],"examTip":"Check verb endings and adjective agreement carefully; accurate grammar scores marks even if your vocabulary choice is simple.","answerTopic":"3.3-translate-fr-0"}]},"notes":[{"id":"fr-1.1","paper":"Paper 1","module":"1.1","title":"Theme 1: People and lifestyle — Identity and relationships with others","specFocus":"Describing yourself and others, family structures and relationships (including blended families), friendship qualities, and discussing arguments and reconciliations.","sourcePages":"Written to match the AQA GCSE French (8652) specification; no supplied booklet for this subject.","summary":"1.1 Identity and relationships with others\nKey vocabulary\n- la famille = family; les parents = parents; le beau-père/la belle-mère = stepfather/stepmother\n- la famille recomposée = blended/step-family; le demi-frère/la demi-sœur = half-brother/half-sister\n- s'entendre bien/mal avec = to get on well/badly with; se disputer (avec) = to argue (with)\n- se réconcilier = to make up; soutenir = to support; faire confiance à = to trust\n- fidèle/la loyauté = loyal/loyalty; bavard(e) = talkative; agaçant(e) = annoying; génial(e) = great\n- de taille moyenne = of medium height; les cheveux bouclés/raides = curly/straight hair\n\nKey grammar\n- Reflexive verbs for relationships: je m'entends, on se dispute, ils se réconcilient (remember the reflexive pronoun agrees with the subject).\n- Perfect tense (passé composé) for past events: mes parents ont divorcé, on s'est réconcilié(e)s (être verbs agree with the subject in gender/number).\n- Giving opinions with justification: à mon avis..., parce que/car..., je trouve que... + adjective.\n- Comparatives for describing people: plus patient que, aussi important que, moins agaçant que.\n\nExam tips\n- Learn adjective agreement for describing family members (grand/grande, gentil/gentille).\n- For speaking and writing, always justify an opinion about relationships with \"parce que\" + a reason, not just an adjective.\n- In listening/reading, watch for negative time markers (ne...jamais, ne...plus) which can reverse the meaning of a sentence about relationships."},{"id":"fr-1.2","paper":"Paper 1","module":"1.2","title":"Theme 1: People and lifestyle — Healthy living and lifestyle","specFocus":"Balanced diets, exercise and fitness, the dangers of smoking/alcohol/drugs, stress and sleep, and giving opinions on healthy versus unhealthy lifestyles.","sourcePages":"Written to match the AQA GCSE French (8652) specification; no supplied booklet for this subject.","summary":"1.2 Healthy living and lifestyle\nKey vocabulary\n- une alimentation équilibrée = a balanced diet; manger sain = to eat healthily\n- faire du sport/rester en forme = to do sport/stay fit; éviter les matières grasses/sucrées = to avoid fatty/sugary foods\n- fumer = to smoke; la drogue/l'alcool = drugs/alcohol; être en bonne/mauvaise santé = to be in good/bad health\n- dormir assez/suivre un régime = to sleep enough/to follow a diet; le stress = stress\n- se détendre = to relax; les matières grasses = fatty foods; nuisible pour la santé = harmful to health\n\nKey grammar\n- Il faut/il ne faut pas + infinitive for giving health advice: il faut manger équilibré, il ne faut pas fumer.\n- Modal verbs: devoir, pouvoir + infinitive (on devrait faire plus de sport).\n- Perfect vs imperfect for past habits/events: quand j'étais petit, je mangeais mal (imperfect); l'année dernière, j'ai arrêté de fumer (perfect).\n- Comparatives for lifestyle choices: le sport est plus sain que de rester devant un écran.\n\nExam tips\n- For writing/speaking tasks on health, always give an opinion with a justification and a piece of advice (il faudrait...).\n- Learn both perfect and imperfect tense forms of manger, faire and être to describe past eating/exercise habits accurately.\n- In reading/listening, look out for negatives (ne...jamais, ne...plus) that can completely change whether a habit is healthy or not."},{"id":"fr-1.3","paper":"Paper 1","module":"1.3","title":"Theme 1: People and lifestyle — Education and work","specFocus":"School life, subjects and timetables, exam pressure, work experience, part-time jobs, and plans for future study or careers.","sourcePages":"Written to match the AQA GCSE French (8652) specification; no supplied booklet for this subject.","summary":"1.3 Education and work\nKey vocabulary\n- le collège/le lycée = middle school/sixth-form college; les matières = school subjects\n- l'emploi du temps = timetable; redoubler = to repeat a year; les devoirs = homework\n- le stage en entreprise = work placement; un petit boulot = a part-time job\n- gagner de l'argent = to earn money; le métier = job/profession; les études supérieures = higher education\n- l'uniforme scolaire = school uniform; la pression des examens = exam pressure; bosser (familiar) = to work hard\n\nKey grammar\n- Near future (futur proche: aller + infinitive) for plans: je vais passer mes examens, je vais faire un stage.\n- Simple future for longer-term plans: j'irai à l'université, je travaillerai à l'étranger.\n- Comparing subjects/opinions: les maths sont plus difficiles que l'histoire; je préfère... à...\n- Perfect tense for past school events: j'ai fait un stage dans une école primaire.\n\nExam tips\n- Learn the near future and simple future forms of aller, faire and être, as career questions almost always need future tense.\n- When giving opinions on school subjects, always justify with \"parce que\" and a specific reason (le prof, les notes, l'intérêt).\n- For role-plays about work experience, prepare set phrases for describing tasks you did (j'ai aidé..., j'ai appris...)."},{"id":"fr-2.1","paper":"Paper 1","module":"2.1","title":"Theme 2: Popular culture — Free-time activities","specFocus":"Hobbies and leisure interests, sport, shopping, reading and cinema, going out with friends, and describing how you spend your free time.","sourcePages":"Written to match the AQA GCSE French (8652) specification; no supplied booklet for this subject.","summary":"2.1 Free-time activities\nKey vocabulary\n- les loisirs/le temps libre = hobbies/free time; faire du shopping = to go shopping\n- jouer aux jeux vidéo = to play video games; aller au cinéma = to go to the cinema\n- pratiquer un sport = to play/practise a sport; sortir avec des amis = to go out with friends\n- lire un roman = to read a novel; bricoler = to do DIY; faire de la musique = to make music\n- être passionné(e) de = to be keen on; de temps en temps = from time to time\n\nKey grammar\n- Frequency expressions: tous les jours, une fois par semaine, de temps en temps, rarement.\n- Present tense of -er/-ir/-re verbs for regular hobbies: je joue, je lis, je sors.\n- Perfect tense for a specific past leisure event: je suis allé(e) au cinéma, j'ai joué au tennis.\n- Giving preferences: je préfère... à..., ce que j'aime le plus, c'est...\n\nExam tips\n- Learn a wide range of leisure verbs (jouer à/de, faire de, aller à) as they are tested very frequently across all four skills.\n- Always add an opinion and reason when describing a hobby, not just a list of activities.\n- In speaking tasks, prepare a short anecdote (perfect tense) about a recent leisure activity in case of an unexpected question."},{"id":"fr-2.2","paper":"Paper 1","module":"2.2","title":"Theme 2: Popular culture — Customs, festivals and celebrations","specFocus":"French and francophone festivals and traditions (Christmas, New Year, Bastille Day, religious and cultural celebrations), family customs, and describing celebrations in the past and future.","sourcePages":"Written to match the AQA GCSE French (8652) specification; no supplied booklet for this subject.","summary":"2.2 Customs, festivals and celebrations\nKey vocabulary\n- une fête/un festival = a celebration/festival; Noël/le Nouvel An = Christmas/New Year\n- la fête nationale (le 14 juillet) = Bastille Day; un anniversaire = a birthday\n- les traditions/les coutumes = traditions/customs; un cadeau = a present\n- un repas de fête = a festive meal; se réunir en famille = to get together as a family\n- les feux d'artifice = fireworks; fêter/célébrer = to celebrate; défiler = to parade\n\nKey grammar\n- Perfect tense for describing past celebrations: on a fêté, j'ai reçu des cadeaux, nous sommes allés au défilé.\n- Near future for upcoming celebrations: on va fêter, je vais inviter.\n- Impersonal expressions: il y a un défilé, c'est l'occasion de...\n- Time expressions for traditions: chaque année, chaque 14 juillet, chaque Noël.\n\nExam tips\n- Festivals are a rich topic for the perfect tense — revise irregular past participles (reçu, vu, fait) as they appear often.\n- Compare a French festival with one from your own culture to show range of language in speaking/writing.\n- In reading/listening, dates and numbers (le 14 juillet, à minuit) are common and worth learning precisely."},{"id":"fr-2.3","paper":"Paper 1","module":"2.3","title":"Theme 2: Popular culture — Celebrity culture","specFocus":"Opinions on fame, role models, influencers and social media stars, the advantages and disadvantages of celebrity status, and the influence of celebrities on young people.","sourcePages":"Written to match the AQA GCSE French (8652) specification; no supplied booklet for this subject.","summary":"2.3 Celebrity culture\nKey vocabulary\n- une célébrité/une vedette = a celebrity/star; un chanteur/une chanteuse = a singer\n- un acteur/une actrice = an actor/actress; un(e) influenceur/influenceuse = an influencer\n- être célèbre = to be famous; la célébrité apporte... = fame brings...\n- un modèle (à suivre) = a role model; la pression médiatique = media pressure\n- les paparazzis = paparazzi; la vie privée = private life; les réseaux sociaux = social media\n\nKey grammar\n- Expressing advantages/disadvantages: d'un côté... de l'autre côté...; l'avantage/l'inconvénient, c'est que...\n- Using superlatives: le chanteur le plus célèbre, la star la plus suivie.\n- Present and perfect tense for describing a celebrity's achievements: il/elle a gagné, il/elle chante, elle est devenue célèbre.\n- Subjunctive-avoiding structures for opinions: je pense que + indicative (keep it simple and accurate at GCSE level).\n\nExam tips\n- Learn both sides of an argument (advantages AND disadvantages of fame) as \"for and against\" questions are common for higher marks.\n- Use varied opinion phrases (à mon avis, selon moi, je trouve que) rather than repeating \"je pense que\" every time.\n- When writing about an influencer or celebrity, include a specific example (name, achievement) to add detail and authenticity."},{"id":"fr-3.1","paper":"Paper 1","module":"3.1","title":"Theme 3: Communication and the world around us — Travel and tourism, including places of interest","specFocus":"Holiday destinations and types of trips, booking accommodation and transport, describing past holidays, places of interest/monuments, and future travel plans.","sourcePages":"Written to match the AQA GCSE French (8652) specification; no supplied booklet for this subject.","summary":"3.1 Travel and tourism, including places of interest\nKey vocabulary\n- partir en vacances = to go on holiday; réserver un hôtel = to book a hotel\n- visiter un monument = to visit a monument; l'office de tourisme = tourist office\n- un endroit touristique = a tourist spot; voyager à l'étranger = to travel abroad\n- prendre l'avion/le train = to take the plane/train; le séjour = the stay\n- découvrir une nouvelle culture = to discover a new culture; un gîte/un camping = a holiday cottage/campsite\n\nKey grammar\n- Perfect tense with être for movement verbs: je suis allé(e), nous sommes partis, elle est restée.\n- Prepositions with countries: aller en France, au Portugal, aux États-Unis.\n- Near future/conditional for holiday plans: je vais visiter, j'aimerais voyager.\n- Imperfect tense for describing weather/scenery in the past: il faisait beau, il y avait beaucoup de monde.\n\nExam tips\n- Learn country prepositions (en/au/aux) carefully — they are tested often in travel contexts.\n- For writing about holidays, combine tenses: what you did (perfect), what it was like (imperfect), and future plans (near future/conditional).\n- In reading/listening passages about tourism, watch for numbers (prices, distances, dates) as they are often targeted in comprehension questions."},{"id":"fr-3.2","paper":"Paper 1","module":"3.2","title":"Theme 3: Communication and the world around us — Media and technology","specFocus":"Smartphones and social media use, the advantages and disadvantages of technology, screen time, online safety/privacy, and opinions on how technology affects young people.","sourcePages":"Written to match the AQA GCSE French (8652) specification; no supplied booklet for this subject.","summary":"3.2 Media and technology\nKey vocabulary\n- un portable/un smartphone = a mobile phone/smartphone; les réseaux sociaux = social media\n- surfer sur Internet = to surf the internet; envoyer un SMS = to send a text message\n- les avantages/les inconvénients = advantages/disadvantages; être accro à = to be addicted to\n- le temps d'écran = screen time; protéger sa vie privée = to protect your privacy\n- télécharger une application = to download an app; partager une photo = to share a photo\n\nKey grammar\n- Expressing advantages and disadvantages: d'un côté... d'un autre côté...; le problème, c'est que...\n- Comparatives/superlatives for technology opinions: plus pratique que, le plus utile.\n- Present tense for habitual technology use: je passe, je publie, je communique.\n- Conditional for suggestions/advice: on devrait limiter, il faudrait faire attention.\n\nExam tips\n- Prepare balanced arguments (for AND against) on social media/technology, since \"advantages and disadvantages\" questions are very common.\n- Learn the verb \"devoir\" in the conditional (je devrais, on devrait) for giving advice about technology use.\n- Reading passages on this topic often include statistics — practise recognising large numbers and percentages in French."},{"id":"fr-3.3","paper":"Paper 1","module":"3.3","title":"Theme 3: Communication and the world around us — The environment and where people live","specFocus":"Environmental issues (pollution, climate change, recycling), descriptions of towns/villages and local areas, advantages/disadvantages of town versus countryside, and solutions to environmental problems.","sourcePages":"Written to match the AQA GCSE French (8652) specification; no supplied booklet for this subject.","summary":"3.3 The environment and where people live\nKey vocabulary\n- l'environnement = the environment; protéger la planète = to protect the planet\n- le recyclage/recycler = recycling/to recycle; les transports en commun = public transport\n- la pollution/le réchauffement climatique = pollution/global warming\n- économiser l'énergie = to save energy; ma ville/mon village = my town/my village\n- les avantages/les inconvénients de la ville/campagne = advantages/disadvantages of the city/countryside\n- les déchets = waste/rubbish; une usine = a factory\n\nKey grammar\n- Il faut/il faudrait + infinitive for environmental solutions: il faut recycler, il faudrait utiliser moins de plastique.\n- Comparatives for town vs countryside: la campagne est plus calme que la ville; il y a moins de pollution.\n- Present tense for habitual eco-actions: je recycle, nous économisons l'eau.\n- Perfect tense for a specific environmental action taken: j'ai participé à un nettoyage de plage.\n\nExam tips\n- Learn \"il faut/il faudrait\" + infinitive thoroughly — almost every environment task asks for solutions/suggestions.\n- Practise comparative structures (plus/moins + adjective + que) for comparing town and countryside living.\n- In listening/reading, local environmental statistics (percentages, amounts of waste) are common — revise numbers carefully."}],"rubrics":{"Paper 1":{"Listen and answer":"AO1 (Listening): marks are awarded for accurate, relevant comprehension of the spoken/written French. Partial credit is given for identifying the correct detail even if the English expression is imperfect; answers must match what is stated, not inferred beyond the text."},"Paper 2":{"Describe the photo":"AO2 (Speaking): assessed on communication of relevant content, range and accuracy of language, and pronunciation/intonation. Higher marks require description plus opinion plus justification, not description alone.","Role-play":"AO2 (Speaking): assessed on task completion (all bullet points covered), appropriateness of response, and ability to deal with an unpredictable question. Accuracy and spontaneity are credited over complexity."},"Paper 3":{"Reading comprehension":"AO3 (Reading): marks for accurate extraction of explicit and implicit meaning from the French text; answers must be supported by the text and expressed clearly in English.","Translate into English":"AO3 (Reading)/translation: marked for accuracy of meaning first, then grammatical accuracy of the English produced; omissions and mistranslations of tense/negatives lose marks."},"Paper 4":{"Write in French":"AO4 (Writing): assessed on content (covering all bullet points), range of vocabulary/structures, accuracy, and quality of opinions with justification. Using a range of tenses accurately accesses higher marks.","Translate into French":"AO4 (Writing)/translation: marked on accuracy of meaning and of French grammar (verb endings, agreement, word order); partial credit is given per correctly translated sense unit."}},"moduleCounts":{"paper1":9,"paper2":9,"paper3":9,"paper4":9},"meta":{"title":"AQA GCSE French","qualification":"GCSE French (8652), specification for first assessment 2026","questionTotal":72,"modulesTotal":9,"provenance":"Questions are original practice items written to match the official AQA GCSE French (8652) specification themes and paper structure (confirmed from aqa.org.uk). They are not official AQA past paper or mark scheme material. Listening items are text-based reading practice, not an audio exam simulation, since this app has no audio playback."}});
